export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-mol-0001", "section": "service", "who": "rubric", "text": "Оглавление"},
  {"id": "cu-mol-0002", "section": "service", "who": "rubric", "text": "О терпении болезней и несчастий"},
  {"id": "cu-mol-0003", "section": "service", "who": "rubric", "text": "^ Праведному Иову Многострадальному"},
  {"id": "cu-mol-0004", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:1"},
  {"id": "cu-mol-0005", "section": "service", "who": "rubric", "text": "Память праведного Твоего Иова, Господи, празднующе,/ тем Тя молим:/ избави нас от наветов и сетей лукавого диавола// и спаси души наша, яко Человеколюбец."},
  {"id": "cu-mol-0006", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0007", "section": "service", "who": "rubric", "text": "Яко истинен и праведен, Богочестив и непорочен,/ освящен же явлься всеславне, Божий угодниче истинный,/ просветил еси мир в терпении твоем, терпеливейший и доблейший.// Темже вси, Богомудре, память твою воспеваем."},
  {"id": "cu-mol-0008", "section": "service", "who": "rubric", "text": "Стихира, глас 6-й:"},
  {"id": "cu-mol-0009", "section": "service", "who": "rubric", "text": "Дал еси нам образ терпения и мужества,/ Преблагий Господи,/ угодника Твоего Иова,/ во всех приключшихся ему злостраданиих/ ничимже согрешивша пред Тобою, ниже устнама своима,/ и не давша безумия Тебе, Богу нашему./ Того молитвами и нас сотвори/ победители многоразличных искушений/ и спаси души наша, яко Человеколюбец."},
  {"id": "cu-mol-0010", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0011", "section": "service", "who": "reader", "text": "Сих святых всех и святаго праведного Иова воспоминая и их богоугодное похваляя житие, Тебе Самаго, в них действовавшаго, восхваляю, и онех благотворения Твоя дарования быти веруя, прилежно молю Тя, Святе святых, даждь ми грешному последовати их учению, житию, любви, вере, долготерпению, и их молитвенною помощию, паче же Твоею вседействующею благодатию, небесныя с ними сподобитися славы, хваляще Пресвятое имя Твое, Отца и Сына и Святаго Духа во веки. Аминь."},
  {"id": "cu-mol-0012", "section": "service", "who": "rubric", "text": "От разных недугов и болезней"},
  {"id": "cu-mol-0013", "section": "service", "who": "rubric", "text": "^ Священномученику Ермолаю, наставнику Пантелеимона, иерею Никомидийскому"},
  {"id": "cu-mol-0014", "section": "service", "who": "rubric", "text": "Тропарь, глас 1-й:2"},
  {"id": "cu-mol-0015", "section": "service", "who": "rubric", "text": "Миром благодати помазан,/ преблаженне отче Ермолае,/ иерей Бога Вышняго явился еси/ и благочестия светлый проповедник,/ мученик же твердый и безмездный врач притекающих к тебе./ Слава Давшему тебе крепость,/ слава Венчавшему тя,// слава Действующему тобою всем исцеления."},
  {"id": "cu-mol-0016", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "cu-mol-0017", "section": "service", "who": "rubric", "text": "Яко святитель благочестно пожив/ и священномучения венец приял еси./ Идольския жертвы погасив,/ добрый пастырь Христова стада был еси, премудре,/ и Пантелеимону истинный учитель./ Сего ради почитаем тя песньми, вопиюще:// от бед избави нас присно молитвами твоими, Ермолае, отче наш."},
  {"id": "cu-mol-0018", "section": "service", "who": "rubric", "text": "Стихира, глас 6-й:"},
  {"id": "cu-mol-0019", "section": "service", "who": "rubric", "text": "Веселися, граде Никомидие,/ радуйся, соборе верных,/ светло торжествующе в памяти Ермолая священномученика,/ скорбящих сострадательнаго утешителя,/ обидимых теплаго заступника,/ болящих безмезднаго врача,/ молящагося о спасении душ наших."},
  {"id": "cu-mol-0020", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0021", "section": "service", "who": "rubric", "text": "О преславный священномучениче Ермолае и скорый помощниче христианом в болезнех! Верую от всея души и помышления, яко дадеся тебе от Господа дар болящия врачевати и расслабленныя укрепляти."},
  {"id": "cu-mol-0022", "section": "service", "who": "reader", "text": "Сего ради к тебе, яко благодатному врачу болезней, аз немощный прибегаю и, твой досточтимый образ с благоговением лобызая, молюся: твоим предстательством у Царя Небеснаго испроси мне болящему исцеление от удручающия мя болезни, аще бо и недостоин есмь тебе, благостнейшаго отца и приснаго заступника моего, но ты, быв подражатель человеколюбия Божия, сотвори мя достойна твоего заступления чрез мое обращение от злых дел к благому житию, уврачуй обильно дарованною тебе благодатию язвы и струпы души и тела моего, даруй ми здравие и спасение и во всем благое поспешение, да тако, тихое и безмолвное житие пожив во всяком благочестии и чистоте, сподоблюся со всеми святыми славити Всесвятое имя Отца и Сына и Святаго Духа. Аминь."},
  {"id": "cu-mol-0023", "section": "service", "who": "rubric", "text": "^ Преподобному Сампсону странноприимцу"},
  {"id": "cu-mol-0024", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:3"},
  {"id": "cu-mol-0025", "section": "service", "who": "rubric", "text": "В терпении твоем стяжал еси мзду твою, отче преподобне,/ в молитвах непрестанно терпевый,/ нищия возлюбивый и сия удовливый,/ но молися Христу Богу, Сампсоне милостиве блаженне,// спастися душам нашим."},
  {"id": "cu-mol-0026", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0027", "section": "service", "who": "rubric", "text": "Яко врача всеизрядна и молитвенника благоприятна,/ к раце твоей Божественней притекающе, Сампсоне Богомудре преподобне,/ сошедшеся любовию, псалмы и песньми радующеся, Христа прославляем,// таковую тебе благодать подавающа исцелений."},
  {"id": "cu-mol-0028", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0029", "section": "service", "who": "rubric", "text": "О, теплый молитвинниче, благостный отче, преподобне Сампсоне! Моли Бога о мне, грешнем, и низпосли от Всеблагаго Владыки помощь ми и избавление, привременна бо есть жизнь моя и исполнена труда, скорбей и болезней."},
  {"id": "cu-mol-0030", "section": "service", "who": "reader", "text": "Укрепи сердце мое, да возмогу понести тяготу мою, и не попусти, да превозмогут искушения многая моя малыя силы, но споспешествуй мне заступлением твоим и посреде обстояний и бед управи путь мой в Царство Небесное, да славлю прославльшагося в тебе Господа во веки. Аминь."},
  {"id": "cu-mol-0031", "section": "service", "who": "rubric", "text": "^ Молитва Архистратигу Михаилу"},
  {"id": "cu-mol-0032", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:4"},
  {"id": "cu-mol-0033", "section": "service", "who": "rubric", "text": "Небесных воинств Архистратиже,/ молим тя присно мы недостойнии,/ да твоими молитвами оградиши нас/ кровом крил невещественныя твоея славы,/ сохраняя нас, припадающих прилежно и вопиющих:/ от бед избави нас,// яко чиноначальник вышних Сил."},
  {"id": "cu-mol-0034", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:5"},
  {"id": "cu-mol-0035", "section": "service", "who": "rubric", "text": "Архистратизи Божии,/ служителие Божественныя славы,/ Ангелов начальницы, и человеков наставницы,/ полезное нам просите, и велию милость,// яко Безплотных Архистратизи."},
  {"id": "cu-mol-0036", "section": "service", "who": "rubric", "text": "^ Молитва Архангелу Рафаилу"},
  {"id": "cu-mol-0037", "section": "service", "who": "rubric", "text": "О святый великий Архангеле Рафаиле, престолу Божию предстояй! Ты благодатию, от всемогущаго Врача душ и телес наших тебе данною, праведнаго мужа Товита от слепоты телесныя исцелил еси, и сына его Товию, спутешествуя ему, от злаго духа сохранил еси."},
  {"id": "cu-mol-0038", "section": "service", "who": "reader", "text": "Всеусердно молю тя, буди мне путеводитель в жизни моей, сохрани от всех видимых и невидимых враг, исцели душевныя и телесныя болезни моя, управи жизнь мою к покаянию во гресех и ко творению добрых дел."},
  {"id": "cu-mol-0039", "section": "service", "who": "reader", "text": "О святый великий Рафаиле Архангеле! Услыши мене грешнаго молящагося тебе и сподоби в здешней и будущей жизни благодарити и славити общаго Создателя нашего в безконечныя веки веков. Аминь."},
  {"id": "cu-mol-0040", "section": "service", "who": "rubric", "text": "^ Мученику Трифону"},
  {"id": "cu-mol-0041", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:6"},
  {"id": "cu-mol-0042", "section": "service", "who": "rubric", "text": "Мученик Твой, Господи, Трифон,/ во страдании своем венец прият нетленный от Тебе, Бога нашего:/ имеяй бо крепость Твою,/ мучителей низложи,/ сокруши и демонов немощныя дерзости./ Того молитвами// спаси души наша."},
  {"id": "cu-mol-0043", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0044", "section": "service", "who": "rubric", "text": "Троическою твердостию/ многобожие разрушил еси от конец, всеславне,/ честен во Христе быв, и, победив мучители во Христе Спасителе,/ венец приял еси мученичества твоего/ и дарования Божественных исцелений,// яко непобедимь."},
  {"id": "cu-mol-0045", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0046", "section": "service", "who": "rubric", "text": "О святый мучениче Христов Трифоне, скорый помощниче и всем к тебе прибегающим и молящимся пред святым твоим образом скоропослушный предстателю!"},
  {"id": "cu-mol-0047", "section": "service", "who": "reader", "text": "Услыши ныне и на всякий час моление нас, недостойных рабов твоих, почитающих святую память твою во всечестнем храме сем, и предстательствуй о нас пред Господем на всяком месте."},
  {"id": "cu-mol-0048", "section": "service", "who": "reader", "text": "Ты бо, угодниче Христов, в великих чудесех возсиявый, источаяй цельбы притекающим к тебе с верою и сущия в скорбех человеки заступаяй, сам обещался еси прежде исхода твоего от жития сего тленнаго молитися за ны ко Господу и испросил еси у Него дар сей: аще кто в какой-либо нужде, печали и болезни душевней или телесней призывати начнет святое имя твое, той да избавлен будет от всякаго прилога злаго."},
  {"id": "cu-mol-0049", "section": "service", "who": "reader", "text": "И якоже ты иногда дщерь цареву, в Риме граде от диавола мучиму, исцелил еси, сице и нас от лютых его козней сохрани во вся дни живота нашего, наипаче же в день последняго нашего издыхания предстательствуй о нас."},
  {"id": "cu-mol-0050", "section": "service", "who": "reader", "text": "Буди нам тогда помощник и скорый прогонитель лукавых духов, и к Царствию Небесному предводитель. И идеже ты ныне предстоиши с лики святых у Престола Божия, моли Господа, да сподобит и нас причастники быти присносущнаго веселия и радости, да с тобою купно прославляем Отца и Сына и Святаго Утешителя Духа во веки. Аминь."},
  {"id": "cu-mol-0051", "section": "service", "who": "rubric", "text": "^ Преподобному Иову Почаевскому"},
  {"id": "cu-mol-0052", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "cu-mol-0053", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0054", "section": "service", "who": "rubric", "text": "Возсия от спуда земнаго сокровище нетленное мощей твоих,/ угодниче Божий,/ яко, благочестно пожив в вере Христа Бога нашего,/ достигл еси добродетелей совершенства,/ и, оставль сладость жития преходящаго,/ в пещере горы Почаевския в пощениих, молитвах и трудех свято подвизался еси,/ и теми тело твое увядил еси./ Ныне же, прешед к Богу в безмятежный и вечный покой,/ молишися о всех с верою к тебе прибегающих./ Радуйся, Иове, преславный угодниче Божий// и обители Почаевския украшение."},
  {"id": "cu-mol-0055", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0056", "section": "service", "who": "reader", "text": "Послуживый Господу и Богу твоему делы благими и неизреченным самоотвержением в трудех, бдениих и пощениих, настави нас на путь всякия добродетели и благостыни, избавляя от искушений и грехов, удаляющих нас от Бога и повергающих в бездну зла все житие наше."},
  {"id": "cu-mol-0057", "section": "service", "who": "reader", "text": "Явивыйся иногда с Пречистою Девою Богородицею верху горы Почаевския во спасение обители твоея от нашествия и обложения агарянскаго, и ныне ускори на помощь стране нашей противу всех врагов наших, внешних и внутренних, утверждая мир и тишину в земли нашей, да безмолвное житие поживем во всяком благочестии и чистоте."},
  {"id": "cu-mol-0058", "section": "service", "who": "reader", "text": "И всем к тебе притекающим и припадающим к раце честных и многоцелебных мощей твоих и твоея помощи и заступления требующим неоскудныя милости независтно подаваяй, не остави и нас, сирых и безпомощных, тебе молящихся, избавляя от всякия скорби, гнева и нужды, от глада, губительства, труса, потопа, огня, меча, нашествия иноплеменник и междоусобныя брани."},
  {"id": "cu-mol-0059", "section": "service", "who": "reader", "text": "Ей, угодниче Божий, призри милостивно от Престола Царя Славы, Емуже ты ныне предстоиши со Архангелы и Ангелы и со всеми святыми, на обитель твою Почаевскую, еюже ты древле мудро правил еси, наздав ю всехвальным и дивным житием твоим, и сохрани ю молитвами твоими и всякий град, и страну и всех отовсюду, на море и на суши, в пустынях и в заключениих многоразличных тебе призывающих, от всех зол, видимых и невидимых, да, тако твоею помощию и ходатайством спасаеми, в веце сем и по скончании живота нашего сподобимся купно с тобою славити и воспевати всечестное имя Отца, и Сына, и Святаго Духа во веки веков. Аминь."},
  {"id": "cu-mol-0060", "section": "service", "who": "rubric", "text": "^ Святому и праведному Иоанну Кронштадтскому"},
  {"id": "cu-mol-0061", "section": "service", "who": "rubric", "text": "Тропарь, глас 1-й:7"},
  {"id": "cu-mol-0062", "section": "service", "who": "rubric", "text": "Православныя веры поборниче,/ земли Российския печальниче,/ пастырем правило и образе верным,/ покаяния и жизни во Христе проповедниче,/ Божественных Таин благоговейный служителю/ и дерзновенный о людех молитвенниче,/ отче праведный Иоанне,/ целителю и предивный чудотворче,/ граду Кронштадту похвало/ и Церкви нашея украшение,/ моли всеблагаго Бога// умирити мир и спасти души наша."},
  {"id": "cu-mol-0063", "section": "service", "who": "rubric", "text": "Кондак, глас 3-й:"},
  {"id": "cu-mol-0064", "section": "service", "who": "rubric", "text": "Днесь пастырь Кронштадтский/ предстоит Престолу Божию/ и усердно молит о верных/ Христа Пастыреначальника,/ обетование давшаго:/ созижду Церковь Мою/ и врата адова// не одолеют ей."},
  {"id": "cu-mol-0065", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0066", "section": "service", "who": "rubric", "text": "О великий угодниче Христов, святый праведный отче Иоанне Кронштадтский, пастырю дивный, скорый помощниче и милостивый предстателю!"},
  {"id": "cu-mol-0067", "section": "service", "who": "reader", "text": "Вознося славословие Триединому Богу, ты молитвенно взывал: Имя Тебе — Любовь: не отвергни меня, заблуждающагося. Имя Тебе — Сила: укрепи меня, изнемогающего и падающаго. Имя Тебе — Свет: просвяти душу мою, омраченную житейскими страстями. Имя Тебе — Мир: умири мятущуюся душу мою."},
  {"id": "cu-mol-0068", "section": "service", "who": "reader", "text": "Ныне благодарная твоему предстательству всероссийская паства молится тебе: Христоименитый и праведный угодниче Божий! Любовию твоею озари нас, грешных и немощных, сподоби нас принести достойные плоды покаяния и не осужденно причащатися Христовых Таин."},
  {"id": "cu-mol-0069", "section": "service", "who": "reader", "text": "Силою твоею веру в нас укрепи, в молитве поддержи, недуги и болезни исцели, от напастей, врагов, видимых и невидимых, избави. Светом лика твоего служителей и предстоятелей Алтаря Христова на святые подвиги пастырского делания подвигни, младенцем воспитание даруй, юное настави, старость поддержи, святыни храмов и святые обители озари!"},
  {"id": "cu-mol-0070", "section": "service", "who": "reader", "text": "Умири, чудотворче и провидче преизряднейший, народы страны нашея, благодатию и даром Святаго Духа избави от междуусобныя брани, расточенная собери, прельщенныя обрати и совокупи Святей Соборней и Апостольской Церкви."},
  {"id": "cu-mol-0071", "section": "service", "who": "reader", "text": "Милостию твоею супружества в мире и единомыслии соблюди, монашествующим в делах благих преуспеяние и благословение даруй, малодушныя утеши, страждущих от духов нечистых свободи, в нуждах и обстояниих сущих помилуй и нас на путь спасения настави."},
  {"id": "cu-mol-0072", "section": "service", "who": "reader", "text": "Во Христе живый, отче наш Иоанне, приведи нас к Невечернему Свету жизни вечныя, да сподобимся с тобою вечнаго блаженства, хваляще и превозносяще Бога во веки веков. Аминь."},
  {"id": "cu-mol-0073", "section": "service", "who": "rubric", "text": "^ Святителю Спиридону чудотворцу, епископу Тримифунтскому"},
  {"id": "cu-mol-0074", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:8"},
  {"id": "cu-mol-0075", "section": "service", "who": "rubric", "text": "Собора Перваго показался еси поборник и чудотворец,/ Богоносе Спиридоне, отче наш./ Темже мертву ты во гробе возгласив,/ и змию в злато претворил еси,/ и внегда пети тебе святыя молитвы/ Ангелы, сослужащия тебе, имел еси, священнейший./ Слава Давшему тебе крепость,/ слава Венчавшему тя,// слава Действующему тобою всем исцеления."},
  {"id": "cu-mol-0076", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0077", "section": "service", "who": "rubric", "text": "Любовию Христовою уязвився, священнейший,/ ум вперив зарею Духа,/ детельным видением твоим деяние обрел еси, Богоприятне,/ жертвенник Божественный быв,// прося всем Божественнаго сияния."},
  {"id": "cu-mol-0078", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0079", "section": "service", "who": "rubric", "text": "О великий и пречудный святителю Христов и чудотворче Спиридоне, Керкирская похвало, всея вселенныя светильниче пресветлый, теплый к Богу молитвенниче и всем к тебе прибегающим и с верою молящимся скоропредстательный заступниче!"},
  {"id": "cu-mol-0080", "section": "service", "who": "reader", "text": "Ты веру православную на Никейстем Соборе посреде отцев преславно изъяснил еси, триединство Святыя Троицы чудесною силою показал еси и еретиков до конца посрамил еси. Услыши нас, грешных, святителю Христов, молящихся тебе, и сильным твоим предстательством у Господа избави нас от всякаго злаго обстояния: от глада, потопа, огня и смертоносныя язвы."},
  {"id": "cu-mol-0081", "section": "service", "who": "reader", "text": "Ты бо во временней жизни своей от всех сих бедствий избавлял еси людей твоих: от нашествия агарян и от глада страну твою сохранил еси, царя от неисцельнаго недуга избавил и многия грешники к покаянию привел еси, мертвых преславно воскрешал еси, за святость же жития твоего Ангелы, невидимо в церкви поющия и сослужащия тебе, имел еси. Сице убо прослави тебе, вернаго Своего раба, Владыка Христос, яко вся тайная человеческая деяния дарова тебе разумети и обличати неправедно живущия."},
  {"id": "cu-mol-0082", "section": "service", "who": "reader", "text": "Многим, в скудости и недостаточестве живущим, ты усердно помогал еси, люди убогия изобильно во время глада напитал еси и ина многа знамения силою в тебе живущаго Духа Божия сотворил еси."},
  {"id": "cu-mol-0083", "section": "service", "who": "reader", "text": "Сице и нас не остави, святителю Христов, поминай нас, чад своих, у Престола Вседержителя и умоли Господа, да подаст многих наших грехов прощение, безбедное и мирное житие да дарует нам, кончины же живота непостыдныя и мирныя, и блаженства вечнаго в будущем веце сподобит нас, да выну возсылаем славу и благодарение Отцу и Сыну и Духу Святому, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0084", "section": "service", "who": "rubric", "text": "^ Святому великомученику и целителю Пантелеимону"},
  {"id": "cu-mol-0085", "section": "service", "who": "rubric", "text": "Тропарь, глас 3-й:9"},
  {"id": "cu-mol-0086", "section": "service", "who": "rubric", "text": "Страстотерпче святый и целебниче Пантелеимоне,/ моли Милостиваго Бога,/ да прегрешений оставление// подаст душам нашим."},
  {"id": "cu-mol-0087", "section": "service", "who": "rubric", "text": "Кондак, глас 5-й:"},
  {"id": "cu-mol-0088", "section": "service", "who": "rubric", "text": "Подражатель сый Милостиваго/, и исцелений благодать от Него прием,/ страстотерпче и мучениче Христа Бога,/ молитвами твоими душевныя наша недуги исцели,/ отгоня присно борца соблазны от вопиющих верно:// спаси ны, Господи."},
  {"id": "cu-mol-0089", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0090", "section": "service", "who": "rubric", "text": "Святый великомучениче и целителю Пантелеимоне, Бога милостиваго подражателю!"},
  {"id": "cu-mol-0091", "section": "service", "who": "reader", "text": "Призри благосердием и услыши нас, грешных, пред святою твоей иконою усердне молящихся."},
  {"id": "cu-mol-0092", "section": "service", "who": "reader", "text": "Испроси нам у Господа Бога, Ему же со Ангелы предстоиши на Небеси, оставление грехов и прегрешений наших."},
  {"id": "cu-mol-0093", "section": "service", "who": "reader", "text": "Исцели болезни душевныя же и телесныя рабов Божиих, ныне поминаемых, зде предстоящих и всех христиан православных, к твоему заступлению притекающих."},
  {"id": "cu-mol-0094", "section": "service", "who": "reader", "text": "Се бо мы, по грехом нашим люте одержимы есмы многими недуги и не имамы помощи и утешения, к тебе же прибегаем, яко дадеся ти благодать молитися за ны и целити всяк недуг и всяку болезнь."},
  {"id": "cu-mol-0095", "section": "service", "who": "reader", "text": "Даруй убо всем нам святыми молитвами твоими здравие и благомощие души и тела, преспеяние веры и благочестия и вся к житию временному и ко спасению потребная."},
  {"id": "cu-mol-0096", "section": "service", "who": "reader", "text": "Яко да, сподобившися тобою великих и богатых милостей, прославим тя и подателя всех благ, дивнаго во святых, Бога нашего, Отца, и Сына, и Святаго Духа. Аминь."},
  {"id": "cu-mol-0097", "section": "service", "who": "rubric", "text": "^ Святому великомученику и целителю Пантелеимону молитва 2-я, наедине от лица болящего читаемая"},
  {"id": "cu-mol-0098", "section": "service", "who": "rubric", "text": "О великий угодниче Христов, страстотерпче и врачу многомилостивый, Пантелеимоне!"},
  {"id": "cu-mol-0099", "section": "service", "who": "reader", "text": "Умилосердися надо мною, грешным рабом, услыши стенание и вопль мой, умилостиви Небеснаго, верховнаго Врача душ и телес наших, Христа Бога нашего, да дарует ми исцеление от гнетущаго мя недуга."},
  {"id": "cu-mol-0100", "section": "service", "who": "reader", "text": "Приими недостойное моление грешнейшаго паче всех человек."},
  {"id": "cu-mol-0101", "section": "service", "who": "reader", "text": "Посети мя благодатным посещением. Не возгнушайся греховных язв моих, помажи елеем милости твоея и исцели мя: да, здрав сый душею и телом, остаток дний моих, благодатию Божиею, возмогу провести в покаянии и угождении Богу и сподоблюся восприяти благий конец живота моего."},
  {"id": "cu-mol-0102", "section": "service", "who": "reader", "text": "Ей, угодниче Божий! Умоли Христа Бога, да предстательством твоим дарует ми здравие телу и спасение души моей. Аминь."},
  {"id": "cu-mol-0103", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице перед Ее иконой «Всех скорбящих радость»"},
  {"id": "cu-mol-0104", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:"},
  {"id": "cu-mol-0105", "section": "service", "who": "rubric", "text": "Всех скорбящих Радосте,/ и обидимых Заступнице,/ и алчущих Питательнице,/ странных Утешение,/ обуреваемых Пристанище,/ больных посещение,/ немощных покров и заступнице,/ Жезл старости,/ Мати Бога Вышняго Ты еси, Пречистая: // потщися, молимся, спастися рабом Твоим."},
  {"id": "cu-mol-0106", "section": "service", "who": "rubric", "text": "Кондак, глас 6-й:10"},
  {"id": "cu-mol-0107", "section": "service", "who": "rubric", "text": "Не имамы иныя помощи,/ не имамы иныя надежды,/ разве Тебе, Владычице./ Ты нам помози:/ на Тебе надеемся и Тобою хвалимся,/ Твои бо есмы раби,// да не постыдимся."},
  {"id": "cu-mol-0108", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0109", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице Богородице, Преблагословенная Мати Христа Бога Спасителя нашего, всех скорбящих Радосте, больных посещение, немощных покрове и заступнице, вдовиц и сирых покровительнице, матерей печальных всенадежная утешительнице, младенцев немощных крепосте, и всем безпомощным всегда готовая помоще и верное прибежище!"},
  {"id": "cu-mol-0110", "section": "service", "who": "reader", "text": "Тебе, о, Всемилостивая, дадеся от Всевышняго благодать во еже всех заступати и избавляти от скорби и болезней, зане Сама лютыя скорби и болезни претерпела еси, взирающи на вольное страдание Сына Твоего возлюбленнаго и Того на кресте распинаема зрящи, егда оружие Симеоном предреченное сердце Твое пройде."},
  {"id": "cu-mol-0111", "section": "service", "who": "reader", "text": "Темже убо, о Мати чадолюбивая, вонми гласу моления нашего, утеши нас в скорби сущих, яко верная радости Ходатаица: предстоящи престолу Пресвятыя Троицы, одесную Сына Твоего, Христа Бога нашего, можеши, аще восхощеши, вся нам полезная испросити."},
  {"id": "cu-mol-0112", "section": "service", "who": "reader", "text": "Сего ради с верою сердечною и любовию от души припадаем к Тебе яко Царице и Владычице и псаломски вопити Тебе дерзаем: слыша, Дщи, и виждь, и приклони ухо Твое, услыши моление наше, и избави нас от обстоящих бед и скорбей; Ты бо прошения всех верных, яко скорбящих радость, исполняеши, и душам их мир и утешение подаеши."},
  {"id": "cu-mol-0113", "section": "service", "who": "reader", "text": "Се зриши беду нашу и скорбь: яви нам милость Твою, посли утешение уязвленному печалию сердцу нашему, покажи и удиви на нас грешных богатство милосердия Твоего, подаждь нам слезы покаяния ко очищению грехов наших и утолению гнева Божия, да с чистым сердцем, совестию благою и надеждою несумненною прибегаем ко Твоему ходатайству и заступлению: приими, всемилостивая наша Владычице Богородице, усердное моление наше Тебе приносимое, и не отрини нас, недостойных, от Твоего благосердия, но подаждь нам избавление от скорби и болезни, защити нас от всякаго навета вражия и клеветы человеческая, буди нам помощница неотступная во все дни жизни нашея, яко да под Твоим матерним покровом всегда пребудем цели и сохранена Твоим заступлением и молитвами к Сыну Твоему и Богу Спасителю нашему, Ему же подобает всякая слава, честь и поклонение, со безначальным Его Отцем и Святым Духом, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0114", "section": "service", "who": "rubric", "text": "^ Бессребреникам и чудотворцам Косме и Дамиану"},
  {"id": "cu-mol-0115", "section": "service", "who": "rubric", "text": "Тропарь, глас 5-й:11"},
  {"id": "cu-mol-0116", "section": "service", "who": "rubric", "text": "Святии безсребреницы и чудотворцы Косьмо и Дамиане,/ посетите немощи наша:// туне приясте, туне дадите нам."},
  {"id": "cu-mol-0117", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0118", "section": "service", "who": "rubric", "text": "Благодать приимше исцелений,/ простираете здравие сущим в нуждах, врачеве,/ чудотворцы преславнии,/ но вашим посещением ратников дерзости низложите,// мир исцеляюще чудесы."},
  {"id": "cu-mol-0119", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0120", "section": "service", "who": "rubric", "text": "К вам, святии безсребреницы и чудотворцы Космо и Дамиане, яко к скорым помощником и теплым молитвенником о спасении нашем, мы, недостойнии, преклоньше колена, прибегаем и, припадающе, усердно вопием: не презрите моления нас, грешных, немощных, во многая беззакония впадших и по вся дни и часы согрешающих."},
  {"id": "cu-mol-0121", "section": "service", "who": "reader", "text": "Умолите Господа, да пробавит нам, недостойным рабом Своим, великия и богатыя Своя милости; избавите нас от всякия скорби и болезни, вы бо прияли есте от Господа и Спаса нашего Иисуса Христа неоскудную благодать исцелений, ради твердыя веры, безмезднаго врачевания и мученическия кончины вашея."},
  {"id": "cu-mol-0122", "section": "service", "who": "reader", "text": "Услышите нас, молящихся, и благоприятным ходатайством вашим испросите у Христа Бога православным людем на враги победу и одоление. Паки, припадающе, прилежно молим: испросите нам от Господа вся благополезная, яже в животе нашем временнем, наипаче же ко спасению вечному служащая, да сподобимся молитвами вашими улучити кончину христианскую, безболезненну, непостыдну, мирну, и да избавимся от козней диавольских и вечныя муки, безконечнаго же и блаженнаго Царствия Небеснаго наследницы будем."},
  {"id": "cu-mol-0123", "section": "service", "who": "reader", "text": "Ей, угодницы Божии, не престайте молящеся за ны, с верою к вам притекающия. Аще бо по множеству грехов наших и несмы достойны милосердия вашего, обаче вы, вернии подражателие человеколюбия Божия суще, сотворите, да принесем плоды достойны покаяния и в вечный покой достигнем, хваляще и благословяще дивнаго во святых Своих Господа и Бога и Спаса нашего Иисуса Христа, и Пречистую Матерь Его, и ваше теплое заступление, всегда, ныне, и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0124", "section": "service", "who": "rubric", "text": "^ Пророку, Предтече и Крестителю Господню Иоанну"},
  {"id": "cu-mol-0125", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:12"},
  {"id": "cu-mol-0126", "section": "service", "who": "rubric", "text": "Память праведнаго с похвалами,/ тебе же довлеет свидетельство Господне, Предтече:/ показал бо ся еси воистину и пророков честнейший,/ яко и в струях крестити сподобился еси Проповеданнаго./ Темже за истину пострадав радуяся,/ благовестил еси и сущим во аде Бога явльшагося плотию,/ вземлющаго грех мира,// и подающаго нам велию милость."},
  {"id": "cu-mol-0127", "section": "service", "who": "rubric", "text": "Кондак, глас 5-й:"},
  {"id": "cu-mol-0128", "section": "service", "who": "rubric", "text": "Предтечево славное усекновение,/ смотрение бысть некое Божественное;/ да и сущим во аде Спасово проповесть пришествие./ Да рыдает убо Иродиа,/ беззаконное убийство испросивши:/ не закон бо Божий, ни живый век возлюби,// но притворный, привременный."},
  {"id": "cu-mol-0129", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0130", "section": "service", "who": "rubric", "text": "Крестителю Христов, проповедниче покаяния, кающагося не презри мене, но совокупляяся с вои Небесными, молися ко Владыце за мене, недостойнаго, унылаго, немощнаго и печальнаго, во многия беды впадшаго, утружденнаго бурными помыслы ума моего."},
  {"id": "cu-mol-0131", "section": "service", "who": "reader", "text": "Аз бо есмь вертеп злых дел, отнюдь не имеяй конца греховному обычаю, пригвожден бо есть ум мой земным вещем. Что сотворю? Не вем. И к кому прибегну, да спасена будет душа моя? Токмо к тебе, святый Иоанне, благодати тезоимените, яко тя пред Господем по Богородице вем больша быти рожденных всех, ты бо сподобился еси коснутися верху Царя Христа, вземлющаго грехи мира, Агнца Божия. Егоже моли за грешную мою душу, да поне отныне, в первый надесять час, понесу тяготу благую и прииму мзду с последними."},
  {"id": "cu-mol-0132", "section": "service", "who": "reader", "text": "Ей, Крестителю Христов, честный Предтече, крайний Пророче, первый во благодати мучениче, постников и пустынников наставниче, чистоты учителю и ближний друже Христов! Тя молю, к тебе прибегаю: не отрини мене от твоего заступления, но возстави мя, низверженнаго многими грехи. Обнови душу мою покаянием, яко вторым крещением, понеже обоего начальник еси: крещением омываяй прародительный грех, покаянием же очищаяй коегождо дело скверно. Очисти мя, грехами оскверненнаго, и понуди внити, аможе ничтоже скверно входит, в Царствие Небесное. Аминь."},
  {"id": "cu-mol-0133", "section": "service", "who": "rubric", "text": "Грудные болезни"},
  {"id": "cu-mol-0134", "section": "service", "who": "rubric", "text": "^ Святому Димитрию, митрополиту Ростовскому"},
  {"id": "cu-mol-0135", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:13"},
  {"id": "cu-mol-0136", "section": "service", "who": "rubric", "text": "Православия ревнителю и раскола искоренителю,/ Российский целебниче, и новый к Богу молитвенниче,/ списаньми твоими буих уцеломудрил еси,/ цевнице духовная, Димитрие блаженне,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0137", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0138", "section": "service", "who": "rubric", "text": "Звезду Российскую от Киева возсиявшую,/ и чрез Новград Северский в Ростов достигшую,/ всю же страну сию ученьми и чудесы озарившую,/ ублажим златословеснаго учителя Димитрия,/ той бо всем вся написа, яже к наставлению,/ да всех приобрящет, якоже Павел Христу,// и спасет правоверием души наша."},
  {"id": "cu-mol-0139", "section": "service", "who": "rubric", "text": "Молитва:14"},
  {"id": "cu-mol-0140", "section": "service", "who": "rubric", "text": "О предивный и преславный чудотворче Димитрие, исцеляяй недуги человеческия! Ты неусыпно молиши Господа Бога нашего о всех грешных: молю убо тя, буди ми ходатай пред Господем и помощник на преоборение страстей ненасытныя плоти моея и на одоление стрел сопротивника моего диавола, имиже уязвляет немощное сердце мое и, аки гладный и лютый зверь, алчет погубити душу мою."},
  {"id": "cu-mol-0141", "section": "service", "who": "reader", "text": "Ты, святителю Христов, моя ограда, ты мое заступление и оружие! За твоим содействием сокрушу вся во мне сопротивная воле Царя царствующих. Ты, великий чудотворче, во дни подвигов твоих в мире сем ревнуя о Православной Церкве Божией, яко истинный и добрый пастырь, неблазненно обличал еси грехи и невежествия людския, и уклонившихся от стези правды в ереси и расколы наставлял еси на путь истины. Споспешествуй убо и мне исправити кратковременный путь жизни моей, да непреткновенно пойду по стези заповедей Божиих и неленостно поработаю Господеви моему Иисусу Христу, яко единому Владыце моему, Искупителю и праведному Судии моему."},
  {"id": "cu-mol-0142", "section": "service", "who": "reader", "text": "К сим же припадая, молюся Ти, угодниче Божий, егда изыти души моей из телесе моего, избави ю от темных мытарств, не имам бо добрых дел ко оправданию моему, не даждь сатане возгордитися победою над немощною душею моею. Избави ю от геены, идеже плач и скрежет зубов, и святыми молитвами твоими сотвори мя причастника Небеснаго Царствия в Троице славимаго Бога, Отца и Сына и Святаго Духа. Аминь."},
  {"id": "cu-mol-0143", "section": "service", "who": "rubric", "text": "Глазные болезни, слепота"},
  {"id": "cu-mol-0144", "section": "service", "who": "rubric", "text": "^ Святому мученику Лонгину Сотнику, иже при Кресте Господни"},
  {"id": "cu-mol-0145", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:15"},
  {"id": "cu-mol-0146", "section": "service", "who": "rubric", "text": "Мученик Твой, Господи, Лонгин,/ во страдании своем венец прият нетленный от Тебе, Бога нашего:/ имеяй бо крепость Твою,/ мучителей низложи,/ сокруши и демонов немощныя дерзости./ Того молитвами// спаси души наша."},
  {"id": "cu-mol-0147", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "cu-mol-0148", "section": "service", "who": "rubric", "text": "Весело возрадовася Церковь/ в памяти днесь приснопамятнаго страдальца Лонгина, взывающи:// Ты моя держава, Христе, и утверждение."},
  {"id": "cu-mol-0149", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0150", "section": "service", "who": "rubric", "text": "О святый мучениче Лонгине! Пилатом повелено тебе было с воинами стати на страже при кресте Господа Иисуса."},
  {"id": "cu-mol-0151", "section": "service", "who": "reader", "text": "Ты же, недуговав очима и исцелев от капли крови Господа, капнувшей тебе в очи, обрел и духовное прозрение и, видя чудеса, при распятии Господа происходившие, и трус, и солнечное затмение, и мертвых из гробов воскресение, исповедал явно Иисуса Христа Сыном Божиим."},
  {"id": "cu-mol-0152", "section": "service", "who": "reader", "text": "И с кустодиею у гроба Господня находясь, и Воскресение Христово в трепете зря, сребренники, даваемые синедрионом за скрытие воскресения, ты отверг и, Христа проповедав, во главу усечен быв."},
  {"id": "cu-mol-0153", "section": "service", "who": "reader", "text": "И по усечении главы вдове некоей, очима недуговавшей, во сне явившись, и ей, обретшей честную главу твою, прозрение даровал еси."},
  {"id": "cu-mol-0154", "section": "service", "who": "reader", "text": "Молим тя, святый мучениче Христов Лонгине, болящим очима яви скорую помощь твою и исцели их, дабы, освободившись от недуга своего, не захотели они видети ничего, распаляющаго сластолюбие, но к созерцанию духовной красоты устремились, славя Бога. Аминь."},
  {"id": "cu-mol-0155", "section": "service", "who": "rubric", "text": "^ Святому равноапостольному великому князю Владимиру, во Святом Крещении Василию, Крестителю Руси"},
  {"id": "cu-mol-0156", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:16"},
  {"id": "cu-mol-0157", "section": "service", "who": "rubric", "text": "Уподобился еси купцу, ищущему добраго бисера,/ славнодержавный Владимире,/ на высоте стола седя матере градов, богоспасаемаго Киева:/ испытуя же и посылая к Царскому граду/ уведети православную веру,/ обрел еси бесценный бисер — Христа,/ избравшаго тя яко втораго Павла,/ и оттрясшаго слепоту во святей купели,/ душевную вкупе и телесную./ Темже празднуем твое успение,/ людие твои суще:// моли спастися державы твоея Российския начальником и множеству владомых."},
  {"id": "cu-mol-0158", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0159", "section": "service", "who": "rubric", "text": "Подобствовав великому апостолу Павлу в сединах, всеславне Владимире,/ вся яко младенческая мудрования, яже о идолех тщания оставль,/ яко муж совершенный украсился еси Божественнаго Крещения багряницею./ И ныне Спасу Христу в веселии предстоя,// моли спастися державы Российския начальником и множеству владомых."},
  {"id": "cu-mol-0160", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0161", "section": "service", "who": "rubric", "text": "О великий и преславный угодниче Божий, богоизбранный и богопрославленный, равноапостольный княже Владимире, святое и великодейственное орудие всеблагаго Промысла о спасении народа Российскаго!"},
  {"id": "cu-mol-0162", "section": "service", "who": "reader", "text": "Ты отринул еси зловерие и нечестие языческое, уверовал еси во Единаго Истиннаго Триипостаснаго Бога и, восприяв святое Крещение, просветил еси светом Божественной веры и благочестия страну Российскую. Славяще убо благодаряще Премилосердаго Творца и Спасителя нашего, славим и благодарим тя, великий пастырю и отче наш, яко тобою познахом спасительную веру Христову и крестихомся во имя Пресвятыя и Пребожественныя Троицы, тою же верою избавихомся от праведнаго осуждения Божия, вечнаго рабства диаволя и адова мучительства, тою верою восприяхом благодать всыновления Богу и надежду наследования Небеснаго блаженства."},
  {"id": "cu-mol-0163", "section": "service", "who": "reader", "text": "Ты еси первейший наш вождь к Начальнику и Совершителю нашего вечного спасения, Господу Иисусу Христу, ты еси ближайший предстатель пред Престолом Царя царствующих и теплый молитвенник и ходатай о стране нашей и о всех людех, ты еси первейший виновник благословений и милостей Божиих, почивающих на нас."},
  {"id": "cu-mol-0164", "section": "service", "who": "reader", "text": "И что еще речем? Не может язык наш изобразити величие и высоту благодеяний твоих, излиянных на нас недостойных. Но, о неразумия и ослепления нашего! Приемше толикая благодеяния, ни во что же вменихом я и отщетихомя спасительных плодов твоих."},
  {"id": "cu-mol-0165", "section": "service", "who": "reader", "text": "Омывшеся бо от греха в купели Крещения и облекшеся в одежду чистоты и невинности, осквернихом сию благодатную одежду студеными деянии и помышлении нашими. Отрекшеся сатаны и аггелов его, паки порабощаемся ему, служаще идолом страстей наших, миру, плоти и злым обычаем века. Сочетавшеся Христу, выну оскорбляем Его беззаконии нашими, многообразными язвами гордости, зависти, злобы, злословия, невоздержания и презорства ко Святей Церкви."},
  {"id": "cu-mol-0166", "section": "service", "who": "reader", "text": "Прилепихомся всецело к суетным благом, аки мняще во веки пребывати на земли, не помышляем о Небе, о душе, о смерти, о суде, о нескончаемей вечности. Сего ради воздвизаем на ся праведный гнев и осуждение Божие, купно же оскорбляем и преогорчеваем твою отчую любовь и попечение о нас, ты бо просветил еси нас святым Крещением, во еже способствовати нам к получению Небеснаго блаженства и земнаго благоденствия, мы же неразумнии злым произволением нашим сами себе подвергаем адовым мукам и временным бедствием!"},
  {"id": "cu-mol-0167", "section": "service", "who": "reader", "text": "Но, о всеблагий отче и просветителю наш, милостив буди к нашим немощем, долготерпелив ко грехом и неправдам нашим, умоли Премилосердаго Царя Небеснаго, да не прогневается на ны зело и не погубит нас со беззаконьми нашими, но да помилует и спасет нас, имиже весть судьбами. Да всадит в сердца наша спасительный страх Свой, да просветит Своею благодатию ум наш, во еже узрети нам бездну погибели, в нюже стремимся, оставити стези нечестия и заблуждений, обратитися же на путь спасения и истины, неуклонно исполняти заповеди Божии и уставы Святыя Церкве."},
  {"id": "cu-mol-0168", "section": "service", "who": "reader", "text": "Моли, благосерде, Человеколюбца Бога, да явит нам великую милость Свою, да избавит нас от нашествия иноплеменников, от внутренних нестроений, мятежей и раздоров, от глада, смертоносных болезней, и от всякаго зла, да подаст нам благорастворение воздуха и плодоносие земли, да сохранит в судящих и начальствующих правду и милость, да даст духовным пастырем непорочность жития и ревность о спасении пасомых, всем же людем усердие в исполнении своих обязанностей, взаимную любовь и единомыслие, стремление ко благу отечества и Святыя Церкве."},
  {"id": "cu-mol-0169", "section": "service", "who": "reader", "text": "Да распространит свет спасительныя веры в стране нашей, во всех концех ея, да обратит к правоверию неверующих, да упразднит вся ереси и расколы, да, тако поживше в мире на земли, сподобимся с тобою вечнаго блаженства, хваляще и превозносяще Бога во веки веков. Аминь."},
  {"id": "cu-mol-0170", "section": "service", "who": "rubric", "text": "^ Святому великомученику Димитрию Солунскому"},
  {"id": "cu-mol-0171", "section": "service", "who": "rubric", "text": "Тропарь, глас 3-й:17"},
  {"id": "cu-mol-0172", "section": "service", "who": "rubric", "text": "Велика обрете в бедах/ тя поборника вселенная, страстотерпче,/ языки побеждающа./ Якоже убо Лиеву низложил еси гордыню,/ и на подвиг дерзновенна сотворив Нестора,/ тако, святе Димитрие,/ Христу Богу молися// даровати нам велию милость."},
  {"id": "cu-mol-0173", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0174", "section": "service", "who": "rubric", "text": "Кровей твоих струями, Димитрие,/ Церковь Бог обагри,/ давый тебе крепость непобедимую,/ и соблюдая град твой невредим:// того бо еси утверждение."},
  {"id": "cu-mol-0175", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0176", "section": "service", "who": "rubric", "text": "Святый и славный великомучениче Христов Димитрие, скорый помощниче и теплый заступниче с верою притекающих к тебе!"},
  {"id": "cu-mol-0177", "section": "service", "who": "reader", "text": "Предстоя с дерзновением Небесному Царю, испроси у Него прощение согрешений наших и о еже избавитися нам от всегубительныя язвы, труса, потопа, огня, меча и вечныя казни."},
  {"id": "cu-mol-0178", "section": "service", "who": "reader", "text": "Моли благость Его, еже ущедрити град сей (обитель сию) и всякую страну христианскую."},
  {"id": "cu-mol-0179", "section": "service", "who": "reader", "text": "Исходатайствуй у Царя царствующих на враги победу и одоление православным христианам, всей державе православной мир, тишину, твердость в вере и преспеяние во благочестии."},
  {"id": "cu-mol-0180", "section": "service", "who": "reader", "text": "Нам же, чтущим честную память твою, испроси благодатное укрепление на дела благая, да благоутробное Владыце нашему Христу Богу зде творяще, сподобимся молитвами твоими наследовати Царствие Небесное для вечнаго прославления Его со Отцем и Святым Духом. Аминь."},
  {"id": "cu-mol-0181", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице перед Ее иконой «Казанская»"},
  {"id": "cu-mol-0182", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:18"},
  {"id": "cu-mol-0183", "section": "service", "who": "rubric", "text": "Заступнице усердная,/ Мати Господа Вышняго,/ за всех молиши Сына Твоего Христа Бога нашего,/ и всем твориши спастися,/ в державный Твой покров прибегающим./ Всех нас заступи, о Госпоже Царице и Владычице,/ иже в напастех и в скорбех, и в болезнех обремененных грехи многими,/ предстоящих и молящихся Тебе умиленною душею/ и сокрушенным сердцем,/ пред пречистым Твоим образом со слезами,/ и невозвратно надежду имущих на Тя,/ избавления всех зол,/ всем полезная даруй,/ и вся спаси, Богородице Дево:// Ты бо еси Божественный покров рабом Твоим."},
  {"id": "cu-mol-0184", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:19"},
  {"id": "cu-mol-0185", "section": "service", "who": "rubric", "text": "Притецем, людие, к тихому сему и доброму пристанищу,/ скорой Помощнице, готовому и теплому спасению, покрову Девы,/ ускорим на молитву и потщимся на покаяние:/ источает бо нам неоскудныя милости Пречистая Богородица,/ предваряет на помощь, и избавляет от великих бед и зол// благонравныя и богобоящияся рабы Своя."},
  {"id": "cu-mol-0186", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0187", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице! Со страхом, верою и любовию пред честною и чудотворною иконою Твоею припадающе, молим Тя: не отврати лица Твоего от прибегающих к Тебе."},
  {"id": "cu-mol-0188", "section": "service", "who": "reader", "text": "Умоли, милосердая Мати, Сына Твоего и Бога нашего, Господа Иисуса Христа, да сохранит мирну страну нашу, Церковь же Свою Святую непоколебиму да соблюдет и от неверия, ересей и раскола да избавит."},
  {"id": "cu-mol-0189", "section": "service", "who": "reader", "text": "Не имамы бо иныя помощи, не имамы иныя надежды, разве Тебе, Пречистая Дево: Ты еси всесильная христиан Помощница и Заступница."},
  {"id": "cu-mol-0190", "section": "service", "who": "reader", "text": "Избави же и всех, с верою Тебе молящихся, от падений греховных, от навета злых человек, от всяких искушений, скорбей, болезней, бед и от внезапныя смерти."},
  {"id": "cu-mol-0191", "section": "service", "who": "reader", "text": "Даруй нам дух сокрушения, смирение сердца, чистоту помышлений, исправление греховныя жизни и оставление прегрешений, да вси, благодарне воспевающе величия и милости Твоя, являемыя над нами зде на земли, сподобимся и Небеснаго Царствия, и тамо со всеми святыми прославим пречестное и великолепое имя Отца, и Сына, и Святаго Духа во веки веков. Аминь."},
  {"id": "cu-mol-0192", "section": "service", "who": "rubric", "text": "^ Святителю Алексию, митрополиту Московскому, всея Руси чудотворцу"},
  {"id": "cu-mol-0193", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:20"},
  {"id": "cu-mol-0194", "section": "service", "who": "rubric", "text": "Яко апостолом сопрестольна,/ и врача предобра, и служителя благоприятна,/ к раце твоей честней притекающе, святителю Алексие Богомудре, чудотворче,/ сошедшеся, любовию в память твою светло празднуем,/ в песнех и пениих радующеся и Христа славяще,/ таковую благодать тебе даровавшаго исцелений// и граду твоему великое утверждение."},
  {"id": "cu-mol-0195", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0196", "section": "service", "who": "rubric", "text": "Божественнаго и пречестнаго святителя Христова,/ новаго чудотворца Алексия,/ верно вси поюще, людие, любовию да ублажим, яко пастыря великаго,/ служителя же и учителя премудра земли Российстей./ Днесь, в память его притекше,/ радостно возопием песнь Богоносному:/ яко имея дерзновение к Богу,/ многообразных нас избави обстояний, да зовем ти:// радуйся, утверждение граду нашему."},
  {"id": "cu-mol-0197", "section": "service", "who": "rubric", "text": "Молитва:21"},
  {"id": "cu-mol-0198", "section": "service", "who": "rubric", "text": "О пречестная и священная главо и благодати Святаго Духа исполненная, Спасово со Отцем обиталище, великий архиерее, теплый наш заступниче, святителю Алексие!"},
  {"id": "cu-mol-0199", "section": "service", "who": "reader", "text": "Предстоя у Престола всех Царя, и наслаждаяся Света Единосущныя Троицы, и херувимски со Ангелы возглашая песнь Трисвятую, велие и неизследованное дерзновение имея ко Всемилостивому Владыце, молися спасти люди паствы твоея, единородный ти язык."},
  {"id": "cu-mol-0200", "section": "service", "who": "reader", "text": "Благостояние святых церквей утверди, архиереи благолепием святительства украси; монашествующия к подвигом добраго течения укрепи."},
  {"id": "cu-mol-0201", "section": "service", "who": "reader", "text": "Град сей (или: весь сию; аще во обители: святую обитель сию) и вся грады и страны добре сохрани и веру святую непорочну тем соблюсти Господа умоли."},
  {"id": "cu-mol-0202", "section": "service", "who": "reader", "text": "Мир весь умири, от глада и пагубы избави ны и от нападения иноплеменных сохрани нас."},
  {"id": "cu-mol-0203", "section": "service", "who": "reader", "text": "Старыя утеши, юныя накажи (научи), безумныя умудри, вдовицы помилуй, сироты заступи, младенцы возрасти, плененныя возврати, немощствующия исцели и везде тепле призывающих тя и с верою притекающих к раце честных и многоцелебных мощей твоих, усердно припадающих и молящих ти ся от всяких напастей и бед ходатайством твоим свободи, да зовем ти: о Богоизбранный пастырю, звездо всесветлая мысленныя тверди, тайнаго Сиона необоримый столпе, миродохновенный цвете райский, всезлатая уста Слова, московская похвало, всея России украшение!"},
  {"id": "cu-mol-0204", "section": "service", "who": "reader", "text": "Моли о нас Всещедраго и Человеколюбиваго Христа Бога нашего, да в день страшнаго пришествия Его шуияго стояния избавит нас и радости святых причастники сотворит со всеми святыми во веки. Аминь."},
  {"id": "cu-mol-0205", "section": "service", "who": "rubric", "text": "^ Святому мученику и архидиакону Лаврентию Римскому"},
  {"id": "cu-mol-0206", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:22"},
  {"id": "cu-mol-0207", "section": "service", "who": "rubric", "text": "Мученик Твой, Господи, Лаврентий/ во страдании своем венец прият нетленный от Тебе, Бога нашего,/ имеяй бо крепость Твою,/ мучителей низложи,/ сокруши и демонов немощныя дерзости./ Того молитвами// спаси души наша."},
  {"id": "cu-mol-0208", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "cu-mol-0209", "section": "service", "who": "rubric", "text": "Огнем Божественным распалив сердце твое,/ огнь страстей до конца испепелил еси,/ страдальцев утверждение, Богоносе мучениче Лаврентие,/ и в страданиих вопиял еси верно:// ничтоже мя разлучит любве Христовы."},
  {"id": "cu-mol-0210", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0211", "section": "service", "who": "rubric", "text": "Зубная боль"},
  {"id": "cu-mol-0212", "section": "service", "who": "rubric", "text": "^ Священномученику Антипе, епископу Пергамскому"},
  {"id": "cu-mol-0213", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:23"},
  {"id": "cu-mol-0214", "section": "service", "who": "rubric", "text": "И нравом причастник,/ и престолом наместник апостолом быв,/ деяние обрел еси, Богодухновенне,/ в видения восход:/ сего ради, слово истины исправляя,/ и веры ради пострадал еси даже до крове,/ священномучениче Антипо,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0215", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "cu-mol-0216", "section": "service", "who": "rubric", "text": "Апостолов сопрестольник и святителей украшение/ был еси, блаженне,/ мученически прославився,/ возсиял еси, якоже солнце, всех просвещая,/ Антипо священне,/ разрушил еси безбожия нощь глубокую./ Сего ради тя почитаем,/ яко Божественнаго суща священномученика// и целеб подателя."},
  {"id": "cu-mol-0217", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0218", "section": "service", "who": "rubric", "text": "О преславный священномучениче Антипо и скорый помощниче христианом в болезнех! Верую от всея души и помышления, яко дадеся тебе от Господа дар болящия исцеляти, недугующия врачевати и разслабленныя укрепляти."},
  {"id": "cu-mol-0219", "section": "service", "who": "reader", "text": "Сего ради к тебе, яко благодатному врачу болезней, аз, немощный (или немощная) прибегаю и, твой досточтимый образ со благоговением лобызая (или лобызающи), молюся: твоим предстательством у Царя Небеснаго испроси мне, болящему (или болящей) исцеление от удручающия мя зубныя болезни, аще бо и недостоин (или недостойна) есмь тебе, благостнейшаго отца и приснаго заступника моего, но ты, быв подражатель человеколюбия Божия, сотвори мя достойна (или достойну) твоего заступления чрез мое обращение от злых дел к благому житию, уврачуй обильно дарованною тебе благодатию язвы и струпы души и тела моего, даруй ми здравие и спасение и во всем благое поспешение, да, тако тихое и безмолвное житие пожив (или поживши) во всяком благочестии и чистоте, сподоблюся со всеми святыми славити всесвятое имя Отца, и Сына, и Святаго Духа. Аминь."},
  {"id": "cu-mol-0220", "section": "service", "who": "rubric", "text": "Болезни сердца"},
  {"id": "cu-mol-0221", "section": "service", "who": "rubric", "text": "^ Святителю Иоасафу, епископу Белгородскому"},
  {"id": "cu-mol-0222", "section": "service", "who": "rubric", "text": "Тропарь, глас 3-й:24"},
  {"id": "cu-mol-0223", "section": "service", "who": "rubric", "text": "Святителю Христу Богу возлюбленне,/ правило веры и образ милосердия людем был еси,/ бдением же, постом и молитвою,/ яко светильник пресветлый просиял еси,/ и прославлен от Бога явился еси;/ телом убо в нетлении почивая,/ духом же престолу Божию предстоя,/ чудеса преславно источаеши./ Моли Христа Бога,// да утвердит нас в Православии и благочестии/ и спасет души наша."},
  {"id": "cu-mol-0224", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0225", "section": "service", "who": "rubric", "text": "Многоразличныя подвиги жития твоего кто исповесть?/ Многообразныя милости Божия тобою явленныя кто исчислит?/ Дерзновение же твое у Пречистыя Богородицы и Всещедраго Бога добре ведуще,/ во умилении сердечнем зовем ти:/ не лиши и нас твоея помощи и заступления,// святителю Христов и чудотворче Иоасафе."},
  {"id": "cu-mol-0226", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0227", "section": "service", "who": "rubric", "text": "О угодниче Божий святителю Иоасафе! Из глубины сердца взываем к тебе раби Божии (имена), огради нас от соблазна, ересей и расколов, научи горняя мудрствовати, рассеянный ум наш просвети и на путь истины направи, охладевшее сердце согрей любовию ко ближнему и ревностию ко исполнению велений Божиих, грехом и нерадением ослабленную волю нашу оживотвори благодатию Духа Всесвятого."},
  {"id": "cu-mol-0228", "section": "service", "who": "reader", "text": "Да твоему пастырскому гласу последующе, сохраним в чистоте и правде души наша, и тако Богу помогающу, Небесного Царствия достигнем, идеже купно с тобою воспрославим пречестное и великолепное имя Отца и Сына и Святаго Духа во веки веков. Аминь."},
  {"id": "cu-mol-0229", "section": "service", "who": "rubric", "text": "Немота"},
  {"id": "cu-mol-0230", "section": "service", "who": "rubric", "text": "^ Преподобному Иоанну Рыльскому"},
  {"id": "cu-mol-0231", "section": "service", "who": "rubric", "text": "Тропарь, глас 1-й:25"},
  {"id": "cu-mol-0232", "section": "service", "who": "rubric", "text": "Покаяния основание, прописание умиления,/ образ утешения, духовнаго совершения,/ равноангельное житие твое бысть, преподобне./ В молитвах убо и пощениих, и в слезах пребывавый,/ отче Иоанне,// моли Христа Бога о душах наших."},
  {"id": "cu-mol-0233", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0234", "section": "service", "who": "rubric", "text": "Ангельскому житию поревновав, преподобне,/ вся земная оставив, ко Христу притекл еси,/ и того заповедьми ограждаяся, явился еси столп непоколебимь от вражиих нападений. Тем зовем ти:// радуйся, отче Иоанне, светило пресветлое."},
  {"id": "cu-mol-0235", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0236", "section": "service", "who": "rubric", "text": "О преподобне и богоносне отче наш Иоанне, зрителю неизреченныя славы в Небеснем Царствии и помощниче благодатный всем к тебе притекающим, не остави места сего, на немже труды и подвиги о Христе подъял еси и землю слезами твоими оросил еси!"},
  {"id": "cu-mol-0237", "section": "service", "who": "reader", "text": "Да пребудет обитель твоя, в нейже благоволи Бог святым твоим мощем почивати, незыблема от ухищрений врагов видимых и невидимых. Укрепи в доброделании чада твоя, ихже во обитель твою собрал еси, яко да познают звание свое и последуют стопам твоим. Страну нашу в мире соблюди. Православным людем во бранех на сопротивныя споборствуй."},
  {"id": "cu-mol-0238", "section": "service", "who": "reader", "text": "Посети с высоты небесныя всех, верно к тебе притекающих и просящих твоего крепкаго заступления; в мори плавающих управи, житейскаго моря волнение утиши, церковныя раздоры укроти, мир всему миру у Господа испроси, болящих уврачуй спасительным посещением, скорбных утеши благодатию, всем буди вся, якоже был еси в земнем житии твоем."},
  {"id": "cu-mol-0239", "section": "service", "who": "reader", "text": "Сотвори о нас к Богу молитву, дана бо ти есть благодать молитися за ны, яко да сподобимся твоим ходатайством улучити вечное блаженство купно с тобою и всеми святыми во Христе Иисусе, Господе нашем, Емуже подобает всякая слава, честь и поклонение со Отцем и Святым Духом во веки веков. Аминь."},
  {"id": "cu-mol-0240", "section": "service", "who": "rubric", "text": "Потеря слуха и болезни ушей"},
  {"id": "cu-mol-0241", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице перед Ее иконой «Нечаянная радость»"},
  {"id": "cu-mol-0242", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:26"},
  {"id": "cu-mol-0243", "section": "service", "who": "rubric", "text": "Днесь, вернии людие, духовно торжествуем,/ прославляюще Заступницу усердную рода христианскаго,/ и притекающе к пречистому Ея образу, взываем сице:/ о, Премилостивая Владычице Богородице,/ подаждь нам нечаянную радость,/ обремененным грехи и скорбьми многими,/ и избави нас от всякаго зла,// молящи Сына Твоего, Христа Бога нашего,/ спасти души наша."},
  {"id": "cu-mol-0244", "section": "service", "who": "rubric", "text": "Кондак, глас 6-й:"},
  {"id": "cu-mol-0245", "section": "service", "who": "rubric", "text": "Не имамы иныя помощи,/ не имамы иныя надежды,/ разве Тебе, Владычице./ Ты нам помози,/ на Тебе надеемся,/ и Тобою хвалимся,/ Твои бо есмы раби,// да не постыдимся."},
  {"id": "cu-mol-0246", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0247", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Всеблагаго Сына Мати Всеблагая, града сего покрове, всех сущих во гресех, скорбех, бедах и болезнех верная Предстательнице и Заступнице!"},
  {"id": "cu-mol-0248", "section": "service", "who": "reader", "text": "Приими молебное пение сие от нас, недостойных рабов Твоих Тебе возносимое; и якоже древле грешника, на всяк день многажды пред честною иконою Твоею молившагося, не презрела еси, но нечаянную радость покаяния тому даровала еси, и усердным к Сыну Твоему ходатайством Сего ко прощению грешника преклонила еси, тако и ныне не презри моления нас, недостойных раб Твоих, но умоли Сына Твоего и Бога нашего, да и всем нам, с верою и умилением пред цельбоносным образом Твоим покланяющимся, по коегождо потребе нечаянную радость дарует."},
  {"id": "cu-mol-0249", "section": "service", "who": "reader", "text": "Да вси на небеси и на земли видят Тя, яко твердую и непостыдную Предстательницу рода христианского, и сие ведуще славят Тя и Тобою Сына Твоего со Безначальным Его Отцем и Единосущным Его Духом, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0250", "section": "service", "who": "rubric", "text": "Болезни чревные, грыжа"},
  {"id": "cu-mol-0251", "section": "service", "who": "rubric", "text": "^ Великомученику Артемию"},
  {"id": "cu-mol-0252", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:27"},
  {"id": "cu-mol-0253", "section": "service", "who": "rubric", "text": "Истинною бо Христовою верою/ утверждься, страстотерпче,/ мучителя злочестива царя/ победил еси со идольским того возношением./ Тем от Царя Великаго, вечно царствующаго,/ пресветлым венцем победным одарен бысть,/ вся исцеляяй болящия и призывающия тя, Артемие великий,/ моли Христа Бога// спасти души наша."},
  {"id": "cu-mol-0254", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0255", "section": "service", "who": "rubric", "text": "Благочестиваго и венценоснаго мученика,/ на враги победы вземшаго одоление,/ сошедшеся, достойно песньми восхвалим Артемия,/ превеликаго в мученицех,/ чудес же дателя пребогатаго,// молится бо Господу о всех нас."},
  {"id": "cu-mol-0256", "section": "service", "who": "rubric", "text": "Славник, глас 2-й:"},
  {"id": "cu-mol-0257", "section": "service", "who": "rubric", "text": "Разумнаго светильника веры, Артемия почтим. Яко обличи царя мерзкаго, и кровию мучения его Церковь Бог обагри. Тем и прият исцелений благодать независтную исцеляти недуги верно приходящих к раце мощей его."},
  {"id": "cu-mol-0258", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0259", "section": "service", "who": "rubric", "text": "Святый мучениче Артемие! Призри с небеснаго чертога на требующих твоея помощи и не отвергни прошений наших, но, яко присный благодетель и ходатай наш, моли Христа Бога, да, человеколюбив и многомилостив сый, сохранит нас от всякаго лютаго обстояния: от труса, потопа, огня, меча, нашествия иноплеменников и междоусобныя брани."},
  {"id": "cu-mol-0260", "section": "service", "who": "reader", "text": "Да не осудит нас грешных по беззаконием нашим, и да не во зло обратим благая, даруемая нам от Всещедраго Бога, но во славу святаго имене Его и в прославление крепкаго твоего заступления."},
  {"id": "cu-mol-0261", "section": "service", "who": "reader", "text": "Да молитвами твоими даст нам Господь мир помыслов, воздержание от пагубных страстей и от всякия скверны и да укрепит во всем мире Свою Едину Святую, Соборную и Апостольскую Церковь, юже стяжал есть честною Своею Кровию."},
  {"id": "cu-mol-0262", "section": "service", "who": "reader", "text": "Молися прилежно, святый мучениче, да благословит Христос Бог державу, да утвердит во святей Своей Православней Церкви живый дух правыя веры и благочестия, да вси члены ея, чистии от суемудрия и суеверия, духом и истиною покланяются Ему и усердно пекутся о соблюдении Его заповедей, да мы вси в мире и благочестии поживем в настоящем веце и достигнем блаженныя вечныя жизни на небеси, благодатию Господа нашего Иисуса Христа, Емуже подобает всякая слава, честь и держава со Отцем и Святым Духом, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0263", "section": "service", "who": "rubric", "text": "^ Преподобному Серафиму Саровскому"},
  {"id": "cu-mol-0264", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:28"},
  {"id": "cu-mol-0265", "section": "service", "who": "rubric", "text": "От юности Христа возлюбил еси, блаженне,/ и Тому Единому работати пламенне вожделев,/ непрестанною молитвою и трудом в пустыни подвизался еси,/ умиленным же сердцем любовь Христову стяжав,/ избранник возлюблен Божия Матере явился еси./ Сего ради вопием ти:// спасай нас молитвами твоими, Серафиме, преподобне отче наш."},
  {"id": "cu-mol-0266", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0267", "section": "service", "who": "rubric", "text": "Мира красоту и яже в нем тленная оставив, преподобне,/ в Саровскую обитель вселился еси,/ и тамо ангельски пожив,/ многим путь был еси ко спасению,/ сего ради и Христос тебе, отче Серафиме, прослави/ и даром исцелений и чудес обогати./ Темже вопием ти:// радуйся, Серафиме, преподобне отче наш."},
  {"id": "cu-mol-0268", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0269", "section": "service", "who": "rubric", "text": "О пречудный отче Серафиме, великий Саровский чудотворче, всем прибегающим к тебе скоропослушный помощниче!"},
  {"id": "cu-mol-0270", "section": "service", "who": "reader", "text": "Во дни земнаго жития твоего никтоже от тебе тощ и неутешен отъиде, но всем в сладость бысть видение лика твоего и благоуветливый глас словес твоих. К сим же и дар исцелений, дар прозрения, дар немощных душ врачевания обилен в тебе явися."},
  {"id": "cu-mol-0271", "section": "service", "who": "reader", "text": "Егда же призва тя Бог от земных трудов к Небесному упокоению, николиже любовь твоя преста от нас, и невозможно есть исчислити чудеса твоя, умножившаяся, яко звезды небесныя: се бо по всем концем земли нашея людем Божиим являешися и даруеши им исцеления."},
  {"id": "cu-mol-0272", "section": "service", "who": "reader", "text": "Темже и мы вопием ти: о претихий и кроткий угодниче Божий, дерзновенный к Нему молитвенниче, николиже призывающия тя отреваяй, вознеси о нас благомощную твою молитву ко Господу Сил, да дарует нам вся благопотребная в жизни сей и вся к душевному спасению полезная, да оградит нас от падений греховных и истинному покаянию научит нас, во еже безпреткновенно внити нам в вечное Небесное Царство, идеже ты ныне в незаходимей сияеши славе, и тамо воспевати со всеми святыми Живоначальную Троицу до скончания века. Аминь."},
  {"id": "cu-mol-0273", "section": "service", "who": "rubric", "text": "^ Преподобному Феодору Студиту"},
  {"id": "cu-mol-0274", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:29"},
  {"id": "cu-mol-0275", "section": "service", "who": "rubric", "text": "Православия наставниче,/ благочестия учителю и чистоты,/ вселенныя светильниче,/ монашествующих Богодухновенное удобрение,/ Феодоре премудре,/ ученьми твоими вся просветил еси,/ цевнице духовная,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0276", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0277", "section": "service", "who": "rubric", "text": "Постническое и равноангельное житие твое/ страдальческими уяснил еси подвиги/ и Ангелом совсельник, Богоблаженне, явился еси, Феодоре./ С ними Христу Богу моляся// не престай о всех нас."},
  {"id": "cu-mol-0278", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0279", "section": "service", "who": "rubric", "text": "О святый Феодоре, исповедник Православия, закона Божия ревнитель, наставник правой веры, помози нам и призри на нас, с верою и усердием прибегающих к тебе!"},
  {"id": "cu-mol-0280", "section": "service", "who": "reader", "text": "От царей иконоборцев за почитание святых икон оковы, изгнание, заточение претерпел ты, преподобный, и множество тяжких ран и жестоких ударов, от которых и болезнь нестерпимую получил."},
  {"id": "cu-mol-0281", "section": "service", "who": "reader", "text": "Великий и досточудный Феодоре, до конца в скорбех претерпевый, и нам, обуреваемым напастьми и треволненьми житейскими, подай крепость душевную и телесную для борьбы с бедами и для одоления страстей и козней вражиих."},
  {"id": "cu-mol-0282", "section": "service", "who": "reader", "text": "Моли о нас Милосердаго Господа, верный раб Божий, Феодоре, да избавит Он нас от ожесточения и хладности сердечной, и дарует нам кротость, безгневие, незлобие, смирение и любовь. Видя помощь Твою, прославим мы Господа и Спаса нашего Иисуса Христа, и тебя, благодетеля нашего, возблагодарим, с благоговением почитая память твою."},
  {"id": "cu-mol-0283", "section": "service", "who": "reader", "text": "О всехвальне, преподобне Феодоре, учением и песньми своими Церковь Божию напоивший и обрадовавший, и нас, ослепленных умом от соблазнов и суеты мира сего, просвети познанием истины и избави от заблуждений и сомнений, чтобы не сообразоватися нам веку сему."},
  {"id": "cu-mol-0284", "section": "service", "who": "reader", "text": "О угодниче Христов, Феодоре, получивший от Бога благодать исцеления недугующих, а наипаче страждущих желудком, уврачуй и нас, одержимых различными недугами и исцели болящих желудком и подай нам здравие, бодрость и мир душевный. Не отрини нас, притекающих к тебе, но заступи и помози нам."},
  {"id": "cu-mol-0285", "section": "service", "who": "reader", "text": "Предстательствуй за нас пред Спасителем нашим, внемли мольбам нашим и исполни прошения наши, да тобою укрепляемы, в трудах и добрых делах совершим мы течение жизни нашей и сподобимся войти в Царствие Небесное, Да вместе с тобою восхвалим и прославим Господа и Спаса нашего Иисуса Христа, со Безначальным Его Отцем и с Пресвятым Духом, ныне, и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0286", "section": "service", "who": "rubric", "text": "^ Праведному Артемию Веркольскому"},
  {"id": "cu-mol-0287", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:30"},
  {"id": "cu-mol-0288", "section": "service", "who": "rubric", "text": "Вышняго повелением,/ тученосным облаком небо помрачившим,/ и молниям блистающим,/ грому же возшумевшу с прещением,/ испустил еси душу твою в руце Господеви,/ премудре Артемие,/ и ныне предстоиши Престолу Владыки всех,/ иже верою и любовию приходящим к тебе,/ подая исцеление всем неотложно,/ и моляся Христу Богу,// спастися душам нашим."},
  {"id": "cu-mol-0289", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0290", "section": "service", "who": "rubric", "text": "Возсия днесь пресветлая память премудраго Артемия;/ Богоданная благодать яко реки изливает от целебных мощей его дивная исцеления,/ имиже от многоразличных недуг избавляемся,/ с верою приемлюще я, и взывающе:// радуйся, Артемие Богомудре."},
  {"id": "cu-mol-0291", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0292", "section": "service", "who": "rubric", "text": "Святый угодниче Божий, праведный Артемие, присный хранителю святыя веры Православныя и близкий защитниче всего севернаго края Российския страны!"},
  {"id": "cu-mol-0293", "section": "service", "who": "reader", "text": "Призри милостивно на усердную молитву нас грешных и твоим благомощным предстательством испроси нам у Господа прощение согрешений наших, преспеяние в вере и благочестии и ограждение от козней диавольских."},
  {"id": "cu-mol-0294", "section": "service", "who": "reader", "text": "Моли Господа, да хранит во здравии и непременяемем благополучии верных людей Своих, да подаст стране нашей мир и тишину, а нам нелицемерное послушание, да сподобит всех нас получити, по христианстей кончине, Небесное Царствие, идеже вси праведнии вместе с тобою, вечно славят Отца и Сына и Святаго Духа. Аминь."},
  {"id": "cu-mol-0295", "section": "service", "who": "rubric", "text": "Болезни ног"},
  {"id": "cu-mol-0296", "section": "service", "who": "rubric", "text": "^ Святому праведному Симеону Верхотурскому"},
  {"id": "cu-mol-0297", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:31"},
  {"id": "cu-mol-0298", "section": "service", "who": "rubric", "text": "Мирскаго мятежа бегая, все желание обратил еси к Богу,/ да в видения восход обрящеши горе,/ отнюдуже не уклонився в лукавствия сердца,/ но очистив душу и тело,/ приял еси благодать точити цельбы верным и неверным,/ притекающим к тебе, праведный Симеоне./ Темже, по данному ти дару,/ испроси у Христа Бога исцеление нам, болящим душевными страстьми,// и моли спасти души наша."},
  {"id": "cu-mol-0299", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0300", "section": "service", "who": "rubric", "text": "Мира суетнаго отверглся еси,/ да блага вечныя жизни наследиши,/ возлюбив незлобие и чистоту души и тела./ Снискал еси, еже возлюбил,/ свидетельствуют бо о сем гроб и нетление мощей твоих,/ и благодать чудотворения наипаче./ Точиши бо цельбы всем притекающим к тебе и непросвещенным,/ Симеоне блаженне,// чудотворче предивный."},
  {"id": "cu-mol-0301", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0302", "section": "service", "who": "rubric", "text": "О святый и праведный Симеоне, чистою душою твоею в Небесных обителех в лице святых водворяяйся, на земли же с нами неотступно пребываяй!"},
  {"id": "cu-mol-0303", "section": "service", "who": "reader", "text": "По данней ти благодати от Господа молитися о нас, милостивно призри на нас, многогрешных, аще и недостойне, обаче с верою и упованием к тебе притекающих, и испроси нам от Бога прощение согрешений наших, в няже впадаем множицею во вся дни жития нашего."},
  {"id": "cu-mol-0304", "section": "service", "who": "reader", "text": "И якоже прежде овым убо, от очныя зельныя болезни ни мало зрети могущим, исцеление очес, овым же, близ смерти бывшим, от лютых недугов врачевание и иным иная многая преславная благодеяния даровал еси, сице избави и нас от недугов душевных и телесных и от всякия скорби и печали и вся благая к настоящему житию нашему и к вечному спасению благопотребная нам от Господа испроси, да тако твоим предстательством и молитвами стяжавше вся нам полезная, аще и недостойнии, благодарне восхваляюще тя, прославим Бога, дивнаго во святых Своих, Отца и Сына и Святаго Духа, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0305", "section": "service", "who": "rubric", "text": "Увечье и боль рук"},
  {"id": "cu-mol-0306", "section": "service", "who": "rubric", "text": "^ Преподобному Иоанну Дамаскину"},
  {"id": "cu-mol-0307", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:"},
  {"id": "cu-mol-0308", "section": "service", "who": "rubric", "text": "В тебе, отче, известно спасеся, еже по образу:/ приим бо крест, последовал еси Христу,/ и дея учил еси презирати убо плоть, преходит бо,/ прилежати же о души, вещи безсмертней.// Темже и со ангелы срадуется, преподобне Иоанне, дух твой."},
  {"id": "cu-mol-0309", "section": "service", "who": "rubric", "text": "Тропарь иной, глас 8-й:"},
  {"id": "cu-mol-0310", "section": "service", "who": "rubric", "text": "Православия наставниче,/ благочестия учителю и чистоты,/ вселенныя светильниче,/ монашествующих Богодохновенное удобрение, Иоанне премудре,/ ученьми твоими вся просветил еси, цевнице духовная,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0311", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:32"},
  {"id": "cu-mol-0312", "section": "service", "who": "rubric", "text": "Песнописца и честнаго Богоглагольника,/ Церкве наказателя и учителя,/ и врагов сопротивоборца, Иоанна воспоим:/ оружие бо взем, Крест Господень,/ всю отрази ересей прелесть,/ и яко теплый предстатель к Богу,// всем подает прегрешений прощение."},
  {"id": "cu-mol-0313", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0314", "section": "service", "who": "rubric", "text": "Преподобне отче Иоанне! Воззри на нас милостивно и к земли приверженных возведи к высоте небесней. Ты горе на небеси, мы на земли низу, удалены от тебе, не толико местом, елико грехми своими и беззаконии, но к тебе прибегаем и взываем: настави нас ходити путем твоим, вразуми и руководствуй."},
  {"id": "cu-mol-0315", "section": "service", "who": "reader", "text": "Вся твоя святая жизнь бысть зерцалом всякия добродетели. Не престани, угодниче Божий, о нас вопия ко Господу. Испроси предстательством своим у Всемилостиваго Бога нашего мир Церкви Его, под знамением креста воинствующей, согласие в вере и единомудрие, суемудрия же и расколов истребление, утверждение во благих делех, больным исцеление, печальным утешение, обиженным заступление, бедствующим помощь. Не посрами нас, к тебе с верою притекающих."},
  {"id": "cu-mol-0316", "section": "service", "who": "reader", "text": "Вси православнии христиане, твоими чудесы исполненнии и милостьми облагодетельствованнии, исповедуют тя быти своего покровителя и заступника. Яви древния милости твоя, и ихже отцем всепомоществовал еси, не отрини и нас, чад их, стопами их к тебе шествующих. Предстояще всечестней иконе твоей, яко тебе живу сущу, припадаем и молимся: приими моления наша и вознеси их на жертвенник благоутробия Божия, да приимем тобою благодать и благовременную в нуждех наших помощь. Укрепи наше малодушие и утверди нас в вере, да несомненно уповаем получити вся благая от благосердия Владыки молитвами твоими."},
  {"id": "cu-mol-0317", "section": "service", "who": "reader", "text": "О превеликий угодниче Божий! Всем нам, с верою притекающим к тебе, помози предстательством твоим ко Господу, и всех нас управи в мире и покаянии скончати живот наш и преселитися со упованием в блаженныя недра Авраамова, идеже ты радостно во трудех и подвизех ныне почиваеши, прославляя со всеми святыми Бога, в Троице славимаго, Отца и Сына и Святаго Духа, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0318", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице в честь Ее иконы «Троеручица»"},
  {"id": "cu-mol-0319", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "cu-mol-0320", "section": "service", "who": "rubric", "text": "Днесь всемирная радость возсия нам велия:/ даровася святей Горе Афонстей/ цельбоносная Твоя, Владычице Богородице, икона,/ со изображением тричисленно и нераздельно пречистых рук Твоих,/ в прославление Святыя Троицы,/ созываеши бо верных и молящихся Тебе о сем познати,/ яко двема Сына и Господа держиши,/ третию же яви на прибежище и покров чтущих Тя,/ от всяких напастей и бед избавляти,/ да вси, притекающии к Тебе верою приемлют неоскудно от всех зол свобождение,/ от врагов защищение,/ сего ради и мы вкупе с Афоном вопием:// радуйся, Благодатная, Господь с Тобою."},
  {"id": "cu-mol-0321", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:33"},
  {"id": "cu-mol-0322", "section": "service", "who": "rubric", "text": "Днесь веселое наста ныне Твое торжество, Богомати Пречистая,/ вси вернии исполнишася радости и веселия,/ яко сподобльшеся изрядно воспети/ предивное явление честнаго образа Твоего/ и рождшагося из Тебе Младенца, истинна же Бога,/ Егоже двема рукама объемлеши,/ и третиею от напастей и бед нас изымаеши,// и избавляеши от всех зол и обстояний."},
  {"id": "cu-mol-0323", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0324", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице, велие чудо святому Иоанну Дамаскину явившая, яко веру истинную – надежду несумненную показавшему! Услыши нас, грешных, пред чудотворною Твоею иконою усердно молящихся и просящих Твоея помощи: не отрини моления сего многих ради прегрешений наших, но, яко Мати милосердия и щедрот, избави нас от болезней, скорбей и печалей, прости содеянныя нами грехи, исполни радости и веселия всех, чтущих святую икону Твою, да радостно воспоем и любовию прославим имя Твое, яко Ты еси от всех родов избранная и благословенная во веки веков. Аминь."},
  {"id": "cu-mol-0325", "section": "service", "who": "rubric", "text": "Горячка, лихорадка, жар"},
  {"id": "cu-mol-0326", "section": "service", "who": "rubric", "text": "^ Первоверховному апостолу Петру"},
  {"id": "cu-mol-0327", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:34"},
  {"id": "cu-mol-0328", "section": "service", "who": "rubric", "text": "Апостолов первопрестольницы/ и вселенныя учителие,/ Владыку всех молите/ мир вселенней даровати// и душам нашим велию милость."},
  {"id": "cu-mol-0329", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:35"},
  {"id": "cu-mol-0330", "section": "service", "who": "rubric", "text": "Твердыя и боговещанныя проповедатели,/ верх апостолов Твоих, Господи,/ приял еси в наслаждение благих Твоих и покой:/ болезни бо онех и смерть приял еси паче всякаго всеплодия,// Едине, сведый сердечная."},
  {"id": "cu-mol-0331", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0332", "section": "service", "who": "rubric", "text": "О святый Петре, великий апостоле, самовидче и сотаинниче Божий, всемощною десницею Учителя твоего приятый из вод волнующихся и крайняго потопления свобождшийся!"},
  {"id": "cu-mol-0333", "section": "service", "who": "reader", "text": "Не забуди и нас убогих, в тине греховней погрязших и волнами житейскаго моря обуреваемых: подаждь нам твою руку крепкую, помози нам и удержи нас от потопления во страстех, похотех, лжах и клеветах. Сотвори и ты с нами милость, тебе от Господа явленную, да не в сомнении и маловерии изгибнем."},
  {"id": "cu-mol-0334", "section": "service", "who": "reader", "text": "Научи нас, учителю наш, проливати слезы покаяния, да плачем горько о деяниих наших в веце сем. И аще твоя слезы, в покаяние излиянныя, милостию Своею покры Господь и Учитель твой, испроси и нам, со дерзновением апостольским, прощения во гресе ежечаснаго."},
  {"id": "cu-mol-0335", "section": "service", "who": "reader", "text": "Град сей, ко святым стопам твоим поверженный, сохрани и от прилучающихся козней лукавых врага спасения нашего огради; воздвигни твои преподобнии руце ко Господу за народ наш, да тихое и безмолвное житие поживем в веце сем до часа, в оньже имать призвати нас Владыка Господь, наш Судия нелицеприятный."},
  {"id": "cu-mol-0336", "section": "service", "who": "reader", "text": "Ты же, о всехвальный апостоле, не отвержи вопля нашего и стенания к тебе, но заступи нас пред Христом, твоим Учителем, да непрестанно славим Его милосердие к нам, со Отцем и Святым Духом, во веки веков. Аминь."},
  {"id": "cu-mol-0337", "section": "service", "who": "rubric", "text": "Женские немощи"},
  {"id": "cu-mol-0338", "section": "service", "who": "rubric", "text": "^ Священномученику Ипатию, епископу Гангрскому"},
  {"id": "cu-mol-0339", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:36"},
  {"id": "cu-mol-0340", "section": "service", "who": "rubric", "text": "Изволением Божественнаго разума/ вперив ум свой в Небесныя обители/ и равно Ангелом житие пожив на земли,/ сего ради мучения красоты венец на своем версе утвердив,/ священномучениче Ипатие,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0341", "section": "service", "who": "rubric", "text": "Другой тропарь, глас 3-й:"},
  {"id": "cu-mol-0342", "section": "service", "who": "rubric", "text": "В прекрасном Церкве апостольския вертограде/ из юна возраста всесильною десницею Божиею насадился еси,/ Богоблаженне отче Ипатие,/ и в ней, яко верен первосвященник,/ верно Богоначальное и Всетворящее Троическое Единство/ проповедал еси во Вселенском Собрании,/ Духа же Святаго в добродетелех исполнен быв,/ велия чудеса сотворив,/ мучением за веру Христову скончався,/ пришел еси в Небесный град,/ идеже Триипостасного Бога зря,/ моли о чествующих тя,// да в Горнем Иерусалиме со святыми жити сподобимся."},
  {"id": "cu-mol-0343", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0344", "section": "service", "who": "rubric", "text": "Римскому отечеству светильник,/ Богозарными лучами концы светя,/ ныне просвети твое празднество поющия, Ипатие,/ прося свыше мира и грехов оставления,// молитвами защити ны, Ипатие многострадальне."},
  {"id": "cu-mol-0345", "section": "service", "who": "rubric", "text": "Другой кондак, глас 2-й:"},
  {"id": "cu-mol-0346", "section": "service", "who": "rubric", "text": "Обитель Триипостаснаго Божества,/ достоблаженне отче Ипатие, быв,/ во вселенную Всетворца Бога воскликнул еси./ Благодарственне же чудодействуя,/ вшел еси в Небесныя обители,/ тамо моли Всесвятую Троицу, молим тя,/ исцелити телеса и души наша// в Богосозданную нашу красоту."},
  {"id": "cu-mol-0347", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0348", "section": "service", "who": "rubric", "text": "Трисолнечного Света светозарная звездо, вводящая в мир Трисолнечный Свет апостольскими твоими, Богоевангельскаго проповедания священноучении, священномучениче, иерарше Христов, Богоблаженне Ипатие."},
  {"id": "cu-mol-0349", "section": "service", "who": "reader", "text": "Ты приял еси от Святыя Троицы равноапостольную благодать, серафимскую в горечестии к Богу любовь, яко же верховнейший апостолов Петр, и херувимскую многоочитую во учении премудрость, яко же вторый Павел. Просветивый премудрым твоим благочестия учением тьмочисленныя народы, присноусердно подражая всемирнаго Учителя, Господа Бога и Спаса нашего Иисуса Христа."},
  {"id": "cu-mol-0350", "section": "service", "who": "reader", "text": "Его же ради всесмиренно молю богоподражательное отеческое твое благоутробие: призри милостивно богосветлыми очима твоима на сущее недостоинство мое, яко всечадолюбивый по Бозе отец, и присноусердный нашего спасения наставниче, и всех в Горних правонеизменный строитель, адамантная Православию стена и пресветлый столп, вводящий второноваго Израиля во всепросветлейший Горний Сион."},
  {"id": "cu-mol-0351", "section": "service", "who": "reader", "text": "Потщися вскоре помоществовати на бранех воинству нашему. Проси же присно у Святыя Троицы всем православным христианом мира и тишины, душевного спасения и многолетняго в телеси здравия, воздуха благорастворения, земли благоплодия, неплодствующим благочадия, и в законе Господнем воспитания, и всех благих умножения."},
  {"id": "cu-mol-0352", "section": "service", "who": "reader", "text": "А после жития коемуждо жизни сея сподоби святыми твоими молитвами улучити христианскую кончину благу, непостыдну и мирну, со всепреподобнейшим исповеданием и со причастием Святых Безсмертных Небесных и Животворящих Христовых Таин, и с молитвомаслием безпрепятное воздушных мытарств прошествие, наследие со святыми всерадостныя присносущныя жизни, в ней же купно со Ангельскими чинми непрестанныя хвалы вознесем Отцу со Единородным Его Сыном и с Пресвятым, Благим и Животворящим Его Духом, и тебе, великое твое отеческое милостивое заступление, ныне, и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0353", "section": "service", "who": "rubric", "text": "Проказа"},
  {"id": "cu-mol-0354", "section": "service", "who": "rubric", "text": "^ Преподобному Антонию Великому"},
  {"id": "cu-mol-0355", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "cu-mol-0356", "section": "service", "who": "rubric", "text": "Ревнителя Илию нравы подражая,/ Крестителю правыми стезями последуя,/ отче Антоние,/ пустыни был еси житель,/ и вселенную утвердил еси молитвами твоими./ Темже моли Христа Бога,// спастися душам нашим."},
  {"id": "cu-mol-0357", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:37"},
  {"id": "cu-mol-0358", "section": "service", "who": "rubric", "text": "Житейския молвы отринув,/ безмолвно житие скончал еси,/ Крестителя подражаяй всяким образом преподобнейший,/ с ним убо тя почитаем,// отцев начальниче Антоние."},
  {"id": "cu-mol-0359", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0360", "section": "service", "who": "rubric", "text": "О великий угодниче Божий, преподобне отче Антоние! Яко имея дерзновение ко Владыце Христу и ко Пречистей Его Матери, буди о нас, недостойных, молитвенник теплый, заступая нас от всяких бед и напастей, да твоими молитвами невредимы от враг видимых и невидимых пребудем. Моли милосердие Божие, да спасет нас от прегрешений наших имиже веси судьбами."},
  {"id": "cu-mol-0361", "section": "service", "who": "reader", "text": "Моли благость Его, еже милостивно храму (дому) сему потребная даровати, жизнь нашу умирити и вся прихожаны храма сего помиловати и спасти души наша, да непрестанно славим, хвалим, поем и величаем Пречестное и Великолепое имя Отца и Сына и Святаго Духа, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0362", "section": "service", "who": "rubric", "text": "Бессонница"},
  {"id": "cu-mol-0363", "section": "service", "who": "rubric", "text": "^ Святым седми отрокам, иже во Ефесе: Максимилиану, Иамвлиху, Мартиниану, Иоанну, Дионисию, Ексакустодиану и Антонину"},
  {"id": "cu-mol-0364", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:38"},
  {"id": "cu-mol-0365", "section": "service", "who": "rubric", "text": "Благочестия проповедники и Воскресения умерших изобразители,/ Церкви столпы седмочисленныя,/ отроки всеблаженныя песньми восхвалим:/ тии бо по многих летех нетления, аки от сна воставше,// всем возвестиша яве мертвых востание."},
  {"id": "cu-mol-0366", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "cu-mol-0367", "section": "service", "who": "rubric", "text": "Прославивый на земли святыя Твоя/ прежде втораго и страшнаго пришествия Твоего, Христе,/ преславным востанием отроков/ показал еси Воскресение неведящим е,/ нетленна одеяния и телеса явив,/ и царя уверил еси вопити:// воистинну есть мертвых востание."},
  {"id": "cu-mol-0368", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0369", "section": "service", "who": "rubric", "text": "О пречуднии святии седмичисленнии отроцы, Ефеса града похвало и всея вселенныя упование! Воззрите с высоты Небесныя славы на ны, любовию память вашу чтущия, наипаче же на младенцы христианския, вашему заступлению от родителей своих препорученныя."},
  {"id": "cu-mol-0370", "section": "service", "who": "reader", "text": "Низведите на ня благословение Христа Бога, рекшаго: оставите детей приходити ко Мне. Болящия убо от них исцелите, скорбящия утешите, сердца их в чистоте соблюдите, кротостию исполните я и в земли сердец их зерно исповедания Божия насадите и укрепите, во еже от силы в силу им возрастати."},
  {"id": "cu-mol-0371", "section": "service", "who": "reader", "text": "И всех нас, святей иконе вашей предстоящих, мощи же ваша с верою лобызающих и тепле вам молящихся, сподобите Царствие Небесное улучити и немолчными гласы радования тамо прославляти великолепое Имя Пресвятыя Троицы, Отца и Сына и Святаго Духа, во веки веков. Аминь."},
  {"id": "cu-mol-0372", "section": "service", "who": "rubric", "text": "^ Святому преподобному Иринарху, затворнику Ростовскому"},
  {"id": "cu-mol-0373", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:39"},
  {"id": "cu-mol-0374", "section": "service", "who": "rubric", "text": "Яко мученика добропроизвольна/ и преподобных удобрение,/ звезду Ростовскую,/ в затворе, узах и веригах Господеви благоугодившаго/ и чудес благодать от Него приемшаго,/ Иринарха предивнаго песньми хвалебными почтим/ и, к нему припадающе, умильно глаголем:/ отче преподобне, моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0375", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0376", "section": "service", "who": "rubric", "text": "Волнений множество жестоким житием преходя,/ изгнание, затвор и узы железныя претерпел еси мужески, Иринарше терпеливодушне,/ нам оставль образ злострадания и терпения твоего,/ озаряя чудес блистаньми с верою приходящих к честному гробу твоему,/ у негоже, яко почесть победную, вериги твоя тяжкие видим,/ от нихже подаеши исцеления недужным./ Сего ради зовем ти:// радуйся, Иринарше, отче предивный."},
  {"id": "cu-mol-0377", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0378", "section": "service", "who": "rubric", "text": "О преподобне отче Иринарше! Се мы молим тя усердно: буди ходатай наш присный, испроси нам от Христа Бога мир, тишину, благоденствие, здравие и спасение, и от всех врагов видимых и невидимых ограждение, покрый же нас ходатайством твоим от нахождения всяких бед и скорбей, паче же от искушения врага темнаго, да вси мы с тобою прославляем всесвятое имя Отца и Сына и Святаго Духа, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0379", "section": "service", "who": "rubric", "text": "Паралич"},
  {"id": "cu-mol-0380", "section": "service", "who": "rubric", "text": "^ Преподобному Иакову, игумену Железноборовскому"},
  {"id": "cu-mol-0381", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:40"},
  {"id": "cu-mol-0382", "section": "service", "who": "rubric", "text": "Небеснаго желая,/ земная возненавидел еси/ и, взем крест свой, последовал еси Христу/ и от Него прием дарования чудес,/ исцеляти недужныя;/ но, яко имея дерзновение ко Святей Троице,/ испроси православным христианом здравие и спасение,/ на враги же победу/ и не забуди, посещая чад своих,/ припадающих к цельбоносному гробу твоему,// Иакове, преподобне отче наш."},
  {"id": "cu-mol-0383", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0384", "section": "service", "who": "rubric", "text": "Сердечная очи, досточудне, ко Господу вперив/ и телесныя страсти из корене исторгая,/ неболезненную жизнь в болезнех восприял еси, преподобне,/ болезнем же лютым даеши исцеление просящим с верою у тебе,/ темже молим тя, досточудне,/ исцели наша болезни душевныя и телесныя, да зовем ти:// радуйся, Иакове Богомудре, отче наш."},
  {"id": "cu-mol-0385", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0386", "section": "service", "who": "rubric", "text": "Преподобне и богоносне отче наш Иакове! Приими ныне нас, тебе усердно молящихся и припадающих ко всечестному и многоцелебному твоему гробу, идеже святое твое и многотрудное покоится тело. Духом же на Небесех предстоя Святей Троицы со Ангелы и преподобных отцев лики, молися о нас, чадех твоих, отче, да избавимся от всяких скорбей, болезней, бед и обстояний, и благочестно поживем в настоящем житии, ходяще в заповедех и оправданиих Господних безпорочно, и да явимся последователи святому и равноангельскому житию твоему."},
  {"id": "cu-mol-0387", "section": "service", "who": "reader", "text": "Ей, преподобне отче, молим тя, испроси нам же и всем, с верою к тебе притекающим, грехов прощение, телесем здравие, исправление жития и вечное спасение, яко да твоим предстательством спасение, славу возсылати сподобимся в Троице славимому Богу, Отцу, и Сыну, и Святому Духу, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0388", "section": "service", "who": "rubric", "text": "Болезни крови"},
  {"id": "cu-mol-0389", "section": "service", "who": "rubric", "text": "^ Мученику Иоанну воину, чудотворцу"},
  {"id": "cu-mol-0390", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:41"},
  {"id": "cu-mol-0391", "section": "service", "who": "rubric", "text": "Блаженство евангельское возлюбив, Богомудре Иоанне,/ чистоту сердца девством почтил еси./ Темже суету мира сего пренебрег,/ устремился еси зрети Бога,/ Иже тя прослави чудесы во врачевании различне страждущих./ Сего ради молим тя:/ проси нам у Христа Господа всяких скорбей избавления// и получения Царства Небеснаго."},
  {"id": "cu-mol-0392", "section": "service", "who": "rubric", "text": "Кондак, глас 6-й:"},
  {"id": "cu-mol-0393", "section": "service", "who": "rubric", "text": "Благочестиваго воина Христова,/ победившаго враги душевныя и телесныя богомудренно,/ Иоанна мученика достодолжно песньми восхвалим,/ чудодействуя бо, подает обильная исцеления страждущим людем/ и молится Господу Богу// от всяких бед спасти правоверныя."},
  {"id": "cu-mol-0394", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0395", "section": "service", "who": "rubric", "text": "О великий Христов мучениче Иоанне, правоверных поборниче, врагов прогонителю и обидимых заступниче! Услыши нас, в бедах и скорбях молящихся тебе, яко дана тебе бысть благодать от Бога печальныя утешати, немощным помогати, неповинныя от напрасныя смерти избавляти и за всех зле страждущих молитися."},
  {"id": "cu-mol-0396", "section": "service", "who": "reader", "text": "Буди убо и нам поборник крепок на вся видимыя и невидимыя враги наша, яко да твоею помощию и поборством по нас посрамятся вси являющии нам злая. Умоли Господа нашего, да сподобит ны грешныя и недостойныя рабы Своя получити от Него неизреченная благая, яже уготова любящим Его, в Троице Святей славимаго Бога, всегда ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0397", "section": "service", "who": "rubric", "text": "Нарывы"},
  {"id": "cu-mol-0398", "section": "service", "who": "rubric", "text": "^ Святым чудотворцам и бессребреникам, мученикам Киру и Иоанну"},
  {"id": "cu-mol-0399", "section": "service", "who": "rubric", "text": "Тропарь, глас 5-й:"},
  {"id": "cu-mol-0400", "section": "service", "who": "rubric", "text": "Святии славнии Кире и Иоанне,/ бессребреницы, мученицы и чудотворцы,/ милосердием своим, яко стеною необоримою, нас оградите от всех бед/ и от врагов видимых и невидимых сохраните// непрестанною вашею молитвою ко Господу."},
  {"id": "cu-mol-0401", "section": "service", "who": "rubric", "text": "Кондак, глас 3-й:"},
  {"id": "cu-mol-0402", "section": "service", "who": "rubric", "text": "От Божественныя благодати дар чудес приемше, святии,/ чудодействуете, непрестанно,/ вся наша страсти рукодейством секуще невидимым,/ Кире Богомудре со Иоанном славным:// вы бо божественнии врачеве есте."},
  {"id": "cu-mol-0403", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0404", "section": "service", "who": "rubric", "text": "О святые чудотворцы и врачи безмездные Кире и Иоанне, прибегаем к вам, от болезней наших страдая люто. Во дни жизни вашея проповедовали вы, яко недуг души тяжелее всех недугов тела и, егда душа грехами болезнует, часто и тело в болезнь впадает."},
  {"id": "cu-mol-0405", "section": "service", "who": "reader", "text": "Знаем мы, что болезнями от грехов очищаемся; умолите же, святые чудотворцы, Господа, да дарует Он прощение согрешений нам, слабым и безпомощным, в болезнях изможденным, да не погибнем, впавши в уныние. Ускорите на помощь нам и исцелите болезни наши, и мы в здравии, покаянии дни наши проведя, в мире окончим жизнь нашу и в день Судный с чистым сердцем предстанем пред очами Судии вселенной, Сердцеведца Бога. Егоже поем и славим во веки веков. Аминь."},
  {"id": "cu-mol-0406", "section": "service", "who": "rubric", "text": "Кожные болезни и язвы"},
  {"id": "cu-mol-0407", "section": "service", "who": "rubric", "text": "^ Праведному Артемию Веркольскому, чудотворцу"},
  {"id": "cu-mol-0408", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:"},
  {"id": "cu-mol-0409", "section": "service", "who": "rubric", "text": "Вышняго повелением,/ тученосным облаком небо помрачившим,/ и молниям блистающим,/ грому же возшумевшу с прещением,/ испустил еси душу твою в руце Господеви,/ премудре Артемие,/ и ныне предстоиши Престолу Владыки всех,/ иже верою и любовию приходящим к тебе,/ подая исцеление всем неотложно,/ и моляся Христу Богу,// спастися душам нашим."},
  {"id": "cu-mol-0410", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0411", "section": "service", "who": "rubric", "text": "Возсия днесь пресветлая память премудраго Артемия;/ Богоданная благодать яко реки изливает от целебных мощей его дивная исцеления,/ имиже от многоразличных недуг избавляемся,/ с верою приемлюще я, и взывающе:// радуйся, Артемие Богомудре."},
  {"id": "cu-mol-0412", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0413", "section": "service", "who": "rubric", "text": "Святый угодниче Божий, праведный Артемие, присный хранителю святыя веры Православныя и близкий защитниче всего севернаго края Российския страны! Призри милостивно на усердную молитву нас грешных и твоим благомощным предстательством испроси нам у Господа прощение согрешений наших, преспеяние в вере и благочестии и ограждение от козней диавольских."},
  {"id": "cu-mol-0414", "section": "service", "who": "reader", "text": "Моли Господа, да хранит во здравии и непременяемем благополучии верных людей Своих, да подаст стране нашей мир и тишину, а нам нелицемерное послушание, да сподобит всех нас получити, по христианстей кончине, Небесное Царствие, идеже вси праведнии вместе с тобою, вечно славят Отца и Сына и Святаго Духа. Аминь."},
  {"id": "cu-mol-0415", "section": "service", "who": "rubric", "text": "Водянка"},
  {"id": "cu-mol-0416", "section": "service", "who": "rubric", "text": "^ Преподобному Ипатию, игумену Руфианскому"},
  {"id": "cu-mol-0417", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:"},
  {"id": "cu-mol-0418", "section": "service", "who": "rubric", "text": "В тебе, отче, известно спасеся, еже по образу:/ приим бо крест, последовал еси Христу,/ и дея учил еси презирати убо плоть, преходит бо,/ прилежати же о души, вещи безсмертней.// Темже и со Ангелы срадуется, преподобне Ипатие, дух твой."},
  {"id": "cu-mol-0419", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "cu-mol-0420", "section": "service", "who": "rubric", "text": "Чистотою душевною божественне вооружився, и непрестанныя молитвы, яко копие вручив крепко, пробол еси бесовская ополчения, преподобне Ипатие, отче наш, моли непрестанно о всех нас."},
  {"id": "cu-mol-0421", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0422", "section": "service", "who": "rubric", "text": "Прославляется Бог в совете правых, ибо возсиял пред людьми свет добродетелей святого Ипатия, прибегая к которому, из глубины сердца взываем: инок совершенный был ты, Ипатий преподобный, многими трудами к вратам небесным очищавший себе путь."},
  {"id": "cu-mol-0423", "section": "service", "who": "reader", "text": "В необитаемую киновию Руфима придя с учениками, ты очистил ее и в прежнее благолепие привел. Там, власяницы делая, в подвигах великих ты пребыл. Дарование получил ты от Господа, Ипатий достохвальный, различные недуги исцелять, а более всего водянку."},
  {"id": "cu-mol-0424", "section": "service", "who": "reader", "text": "Призри же на страждущих тяжкою болезнею этой, святый Ипатий, и умилостиви твоею благоприятною молитвою Господа, и престань немощным невидимою чудодейственною силою Божию, исцеляя их по великой милости Господней, и пусть, почувствовав облегчение в теле и бодрость духа, отвергнут они нерадение и ревностно пойдут по лестнице добродетелей, простираясь на преуспеяние в богоугодных делах, и славя Отца и Сына, и Святаго Духа, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0425", "section": "service", "who": "rubric", "text": "Расслабление тела, связанное с бессонницей, потерей аппетита и лишением каких-либо членов"},
  {"id": "cu-mol-0426", "section": "service", "who": "rubric", "text": "^ Преподобному Никите Столпнику, Переяславскому чудотворцу"},
  {"id": "cu-mol-0427", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "cu-mol-0428", "section": "service", "who": "rubric", "text": "Христову мученику тезоименит был еси, преподобне, / многи подвиги и труды претерпел еси Христа ради, / Егоже ради вериги носил еси, блаженне, / Того ныне о нас моли, Никито преподобне, / душевныя наша и телесныя страсти уврачевати, / иже верою и любовию // почитающих присно память твою."},
  {"id": "cu-mol-0429", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:42"},
  {"id": "cu-mol-0430", "section": "service", "who": "rubric", "text": "Христа ради от твоих рабов нуждную смерть претерпел еси/ и венец нетления от Него восприял еси,/ приходящим же с верою от честнаго твоего гроба подаеши цельбы,/ о Никито преподобне,// молитвенниче о душах наших."},
  {"id": "cu-mol-0431", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0432", "section": "service", "who": "rubric", "text": "О всечестная главо, преподобне отче преблаженне, Никито преподобномучениче! Не забуди нищих твоих до конца, но поминай нас всегда во святых своих и благоприятных молитвах к Богу и не забуди присещати чад своих."},
  {"id": "cu-mol-0433", "section": "service", "who": "reader", "text": "Моли за ны, отче благий и избранниче Христов, яко имеяй дерзновение к Небесному Царю, и не премолчи за ны ко Господу, и не презри нас, верою и любовию чтущих тя. Поминай нас, недостойных, у Престола Вседержителева и не престай моляся за нас ко Христу Богу: тебе бо дана бысть благодать молитися за ны."},
  {"id": "cu-mol-0434", "section": "service", "who": "reader", "text": "Не мним бо тя мертва суща, аще бо и телом преставился еси от нас, но и по смерти убо жив пребываеши. Не отступай от нас духом, сохраняя и соблюдая нас от стрел вражиих и всякия прелести бесовския, заступниче и молитвенниче наш добрый. Аще бо и мощей твоих рака пред очима нашима видима есть всегда, но святая твоя душа со ангельскими воинствы, со Безплотными лики, с Небесными силами у Престола Вседержителя Бога достойно веселится."},
  {"id": "cu-mol-0435", "section": "service", "who": "reader", "text": "Ведуще убо тя воистинну и по смерти жива суща, тебе припадаем, и тебе молимся, и милися деем, еже молитися о нас Всесильному Богу о пользе душ наших, и испроси нам время на покаяние и невозбранно прейти от земли на Небо, и горьких мытарств, и воздушных князей, и вечныя муки избавится нам, и Небесному Царствию наследником быти со всеми праведными, от века угодившими Ему, Господу нашему Иисусу Христу. Емуже подобает всякая слава, честь и поклонение со Безначальным Его Отцем и Святым Духом, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0436", "section": "service", "who": "rubric", "text": "Рак"},
  {"id": "cu-mol-0437", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице в честь Ее иконы «Всецарица» (Пантанасса)"},
  {"id": "cu-mol-0438", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "cu-mol-0439", "section": "service", "who": "rubric", "text": "Образом радостотворным честныя Всецарицы,/ желанием теплым взыскающих благодати Твоея спаси, Владычице,/ избави от обстояний к Тебе прибегающих;/ от всякия напасти огради стадо Твое,// к заступлению Твоему взывающее присно."},
  {"id": "cu-mol-0440", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0441", "section": "service", "who": "rubric", "text": "Новоявленней Твоей иконе предстояще вернии, умильно воспеваем Ти, Всецарице, раби Твои; низпосли цельбы к Тебе притекающим ныне рабом Твоим, да вси радостно зовем Ти: Радуйся, Всецарице, недуги наша благодатию исцеляющая."},
  {"id": "cu-mol-0442", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0443", "section": "service", "who": "rubric", "text": "О Всеблагая, досточудная Богородице Пантанасса, Всецарице! Несмь достоин, да внидеши под кров мой, но яко милостиваго Бога любоблагоутробная Мати, рцы слово, да исцелится душа моя и укрепится немощствующее тело мое. Имаши бо державу непобедимую, и не изнеможет у Тебе всяк глагол, о Всецарице! Ты за мя упроси, Ты за мя умоли, да прославляю преславное имя Твое всегда, ныне и в безконечныя веки. Аминь."},
  {"id": "cu-mol-0444", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице в честь Ее иконы «Всецарица» (Пантанасса). Молитва 2-я43"},
  {"id": "cu-mol-0445", "section": "service", "who": "rubric", "text": "О Пречистая Богомати, Всецарице! Услыши многоболезненное воздыхание наше пред чудотворною иконою Твоею, из удела Афонскаго в Россию пренесенною, призри на чад Твоих, неисцельными недуги страждущих и ко святому образу Твоему с верою припадающих!"},
  {"id": "cu-mol-0446", "section": "service", "who": "reader", "text": "Якоже птица крилома покрывает птенцы своя, тако и Ты ныне, присно жива сущи, покрый нас многоцелебным Твоим омофором. Тамо, идеже надежда исчезает, несумненною надеждою буди. Тамо, идеже лютыя скорби превозмогают, терпением и ослабою явися. Тамо, идеже мрак отчаяния в души вселися, да возсияет неизреченный свет Божества! Малодушныя утеши, немощныя укрепи, ожесточенным сердцам умягчение и просвещение даруй."},
  {"id": "cu-mol-0447", "section": "service", "who": "reader", "text": "Исцели болящия люди Твоя, о, всемилостивая Царице! Ум и руки врачующих нас благослови, да послужат орудием всемощнаго Врача Христа Спаса нашего."},
  {"id": "cu-mol-0448", "section": "service", "who": "reader", "text": "Яко живей Ти сущей с нами, молимся пред иконою Твоею, о, Владычице! Простри руце Твои, исполненныя исцеления и врачбы, Радосте скорбящих, в печалех Утешение, да чудотворную помощь скоро получив, прославляем Живоначальную и Нераздельную Троицу, Отца, и Сына, и Святаго Духа во веки веков. Аминь."},
  {"id": "cu-mol-0449", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице в честь Ее иконы «Скоропослушница»"},
  {"id": "cu-mol-0450", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:44"},
  {"id": "cu-mol-0451", "section": "service", "who": "rubric", "text": "К Богородице притецем, сущии в бедах,/ и святей иконе Ея ныне припадем,/ с верою зовуще из глубины души:/ скоро наше услыши моление, Дево,/ яко Скоропослушница нарекшаяся,/ Тебе бо раби Твои в нуждах// готовую Помощницу имамы."},
  {"id": "cu-mol-0452", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "cu-mol-0453", "section": "service", "who": "rubric", "text": "В мори житейстем обуреваемии,/ треволнению подпадаем страстей и искушений./ Подаждь убо нам, Госпоже, руку помощи, якоже Петрови Сын Твой,/ и ускори от бед избавити ны, да зовем Ти:// радуйся, всеблагая Скоропослушнице."},
  {"id": "cu-mol-0454", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0455", "section": "service", "who": "rubric", "text": "Преблагословенная Владычице, Приснодево Богородице, Бога Слова паче всякаго слова на спасение наше рождшая, и благодать Его преизобильно паче всех приявшая, море явльшаяся Божественных дарований и чудес приснотекущая река, изливающая благость всем, с верою к Тебе прибегающим!"},
  {"id": "cu-mol-0456", "section": "service", "who": "reader", "text": "Чудотворному Твоему образу припадающе, молимся Тебе, всещедрей Матери Человеколюбиваго Владыки: удиви на нас пребогатыя милости Твоя, и прошения наша, приносимая Тебе, Скоропослушнице, ускори исполнити, все, еже на пользу во утешение и спасение коемуждо устрояющи."},
  {"id": "cu-mol-0457", "section": "service", "who": "reader", "text": "Посети, Преблагая, рабы Твоя благодатию Твоею, подаждь недугующим цельбу и совершенное здравие, обуреваемым тишину, плененным свободу и различными образы страждущих утеши, избави, всемилостивая Госпоже, всяк град и страну от глада, язвы, труса, потопа, огня, меча и иныя казни временныя и вечныя, Матерним Твоим дерзновением отвращающи гнев Божий: и душевнаго разслабления, обуревания страстей и грехопадений свободи рабы Твоя, яко да непреткновенно во всяком благочестии поживше в сем веце, и в будущем вечных благ сподобимся благодатию и человеколюбием Сына Твоего и Бога, Емуже подобает всякая слава, честь и поклонение, со Безначальным Его Отцем и Пресвятым Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0458", "section": "service", "who": "rubric", "text": "^ Святителю Нектарию Эгинскому"},
  {"id": "cu-mol-0459", "section": "service", "who": "rubric", "text": "Тропарь, глас 1-й:"},
  {"id": "cu-mol-0460", "section": "service", "who": "rubric", "text": "Силиврии отрасль и Эгины хранителя, в последняя лета явльшагося, добродетели друга искренняго, Нектария почтим вернии, яко божественнаго служителя Христова: точит бо цельбы многоразличныя благочестно вопиющим: слава прославльшему тя Христу, слава давшему ти чудес благодать, слава действующему тобою всем исцеления."},
  {"id": "cu-mol-0461", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:46"},
  {"id": "cu-mol-0462", "section": "service", "who": "rubric", "text": "Божественный гром, труба духовная, веры насадителю и отсекателю ересей, Троицы угодниче, великий святителю Нектарие, со Ангелы предстоя присно, моли непрестанно о всех нас."},
  {"id": "cu-mol-0463", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "cu-mol-0464", "section": "service", "who": "rubric", "text": "О святителю Нектарие, отче Богомудрый! Приими, блюстителю веры православныя, исповедание устен людей христоименитых, собранных днесь в храме благодатию Божиею, в тебе живущею. Весть бо достиже до предел Российских, яко ты, велий во святых угодниче Христов, во всех концех вселенныя призывающим имя твое являешися и от раковыя болезни исцеление даруеши."},
  {"id": "cu-mol-0465", "section": "service", "who": "reader", "text": "Слышахом об иерее, тебе тезоименитом и храм во имя твое созидавшем со скорбьми велиими. Раковою убо язвою грудною поражен бе, крови на всяк день точащейся, и страждаше люте, дела же своего святаго не оставляше. Внезапу ты, святителю многомилостиво, с Небесе сшед, ему во храме предстал еси в видимом образе. Он же непщуя тя собрата едина от смертных быти, прошаше молитв твоих и рече: «Боляй есмь вельми, обаче хощу святый олтарь наздати, да поне единожды святую Литургию вкупе с прихожаны совершу; послежде и умрети готов есмь, смерть бо мя не страшит». Ты же, отче, безплотен сый, слезами лице свое орошаше! и объем страдальца, лобызаше и глаголя: «Не тужи, чадо мое, яко, болезнию испытан, здрав будеши. Вси убо о чудеси сем ведати имут». Он же, исцелен быв, абие разуме, с кем беседоваше, тебе невидиму бывшу."},
  {"id": "cu-mol-0466", "section": "service", "who": "reader", "text": "О великий угодниче Христов Нектарие! Храм оный свершен есть ныне, и чудеса твои аки море преизливающееся умножишася! Мы же познахом, яко молитве праведника должно поспешествуемой быти усердием нашим к службе Божией и решимостью за Христа умирати, да здрави обрящемся. Молят тя, отче праведный, болящая чада твоя: да совершается с нами воля Божия, благая, угодная и совершенная, не хотящи смерти грешнику, но еже обратитися и живу быти ему. Ты же, провозвестниче воли Божией, исцели ны благодатным явлением своим, да велик будет Бог на Небеси и на земли во веки веков! Аминь."},
  {"id": "cu-mol-0467", "section": "service", "who": "rubric", "text": "Молитвы об исцелении болящего"},
  {"id": "cu-mol-0468", "section": "service", "who": "rubric", "text": "^ Молитва 1-я47"},
  {"id": "cu-mol-0469", "section": "service", "who": "rubric", "text": "Владыко, Вседержителю, святый Царю, наказуяй и не умерщвляяй, утверждаяй низпадающия и возводяй низверженныя, телесныя человеков скорби исправляяй, молимся Тебе, Боже наш, раба Твоего (имя) немощствующа посети милостию Твоею, прости ему всякое согрешение вольное и невольное."},
  {"id": "cu-mol-0470", "section": "service", "who": "reader", "text": "Ей, Господи, врачебную Твою силу с небесе низпосли, прикоснися телеси, угаси огневицу, укроти страсть и всякую немощь таящуюся, буди врач раба Твоего (имя), воздвигни его от одра болезненнаго и от ложа озлобления цела и всесовершенна, даруй его Церкви Твоей благоугождающа и творяща волю Твою. Твое бо есть, еже миловати и спасати ны, Боже наш, и Тебе славу возсылаем, Отцу и Сыну и Святому Духу, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0471", "section": "service", "who": "rubric", "text": "^ Молитва 2-я"},
  {"id": "cu-mol-0472", "section": "service", "who": "rubric", "text": "О Премилосердый Боже, Отче, Сыне и Святый Душе, в Нераздельней Троице покланяемый и славимый, призри благоутробно на раба Твоего (имя), болезнию одержимаго; отпусти ему вся согрешения его; подай ему исцеление от болезни; возврати ему здравие и силы телесные; подай ему долгоденственное и благоденственное житие, мирныя Твои и премирныя блага, чтобы он вместе с нами приносил благодарныя мольбы Тебе, Всещедрому Богу и Создателю нашему."},
  {"id": "cu-mol-0473", "section": "service", "who": "reader", "text": "Пресвятая Богородица, всесильным заступлением Твоим помоги мне умолить Сына Твоего, Бога моего, об исцелении раба Божия (имя)."},
  {"id": "cu-mol-0474", "section": "service", "who": "reader", "text": "Все святые и ангелы Господни, молите Бога о больном рабе Его (имя). Аминь."},
];

